quests[34945] = { id = 34945, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag - Underseer Bloodmane Vignette" }
quests[34946] = { id = 34946, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Morkurk Greeting" }
quests[34947] = { id = 34947, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Manual", description = "Hey! I hear there's a curious object nearby. Scouts say it's some kind of shredder manual.\n\nGo check it out for me, will ya? I wonder if it has to do with this new prototype I've been hearin' about...", completion = "These orders appear to have come from Orgrim Doomhammer.", objectives = "Find the Iron Shredder Decommission Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34948] = { id = 34948, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shredder Manual", description = "I've been hearing rumors of this new prototype shredder the Iron Horde's engineers have been working on.\n\nI think we ought to investigate. A shadow hunter spotted some sort of shredder manual, and it might have something to do with that prototype.", completion = "These orders appear to have come from Orgrim Doomhammer.", objectives = "Find the Iron Shredder Decommission Orders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34949] = { id = 34949, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Ranks", objectives = "We've had quite the journey in getting your tower burning bright. If it's agreeable to you, I'd like to join your campaign.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34950] = { id = 34950, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadpiston", description = "Nearby, a group of Iron Horde took over a key strategic position with surprising alacrity.\n\nThey used a machine they call Dreadpiston to terrible effect in the siege, and I believe we need to destroy that machine before moving against the Iron Horde in Tuurem.", completion = "An infernal machine.", objectives = "Defeat Dreadpiston.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34951] = { id = 34951, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Call Him Lantresor of the Blade", description = "The Burning Blade clan at Hallvalor is supplying the Warsong with weapons and warriors. We cannot let this continue.\n\nThere's a young blademaster who's been exiled from the Burning Blade for many years. They call him Lantresor of the Blade.\n\nMy rangari recently saw him return to Hallvalor to challenge the blademaster leadership. Instead, they clapped him in chains.\n\nMaybe he's still alive. Maybe he'll help you deal with the Burning Blade.", completion = "Who are you?\n\nDon't you know death by sight, {class}?", objectives = "Find Lantresor of the Blade in Hallvalor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34952] = { id = 34952, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Friend o' My Enemy", description = "Hallvalor is the ancestral home o' the Burning Blade clan. Since they be such fast friends, the Warsong allow the blademasters an' their shaman to remain in Nagrand when all o' the other clans are forced out.\n\nBlah, blah, blah.\n\nI say, if they're the friend o' my enemy, then they're my enemy, and that's all I need to know!", completion = "You done us a solid with them Burning Blade, lad, and we're not the forgettin' kind.\n\nLet's celebrate o'er a pint in an hour. Drinks are on me.", objectives = "Kill 15 Burning Blade forces at Hallvalor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34953] = { id = 34953, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Burning Blade", description = "Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed.\n\nI want justice.\n\nI suspect you won't mind killing along the way. Not that you'll have any choice.", completion = "You done us a solid with them Burning Blade, lad, and we're not the forgettin' kind.\n\nLet's celebrate o'er a pint in an hour. Drinks are on me.", objectives = "Kill 15 Burning Blade forces at Hallvalor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34954] = { id = 34954, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blade Itself", description = "When they clapped me in irons, the Burning Blade instructor, Luhk the Keen-Eyed, took my blade. He's an honorable orc, even if his training techniques are counter-productive.\n\nI want my blade back, {class}.", progress = "A blademaster without a blade is no blademaster at all.", completion = "If you can defeat Luhk, then perhaps there's some hope for you after all.", objectives = "Retrieve Lantresor's Blade from Instructor Luhk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34955] = { id = 34955, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Without My Honor", description = "The blade is not the only important item a blademaster carries.\n\nOnce he has passed his final tests in the Masters' Caverns, the blademaster is given the honor of wearing the Burning Blade's banner.\n\nWhen my petition to reclaim my rightful place with the clan fell upon deaf and craven ears, I was stripped of that honor.\n\nNo doubt, my banner has been stored away somewhere in Hallvalor. They'll give it to some other aspiring blademaster if they don't burn it first.", progress = "Do you have my banner?", completion = "I don't expect you to understand the importance of what you've done.\n\nPerhaps one day you will.", objectives = "Find the Blademaster's Banner in a Burning Blade Locker.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34956] = { id = 34956, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meet Me in the Cavern", description = "It's time, {class}. Time to face the masters.", completion = "You made it. Good.\n\nGetting in here was nothing compared to what's to come.", objectives = "Meet up with Lantresor of the Blade inside the Masters' Cavern.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34957] = { id = 34957, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Challenge of the Masters", description = "The time has come to challenge the Burning Blade masters.\n\nGo to the back of the cavern. There you will find the challenge ring and the masters watching over it from above.\n\nPull the blade from the middle of the ring to issue your challenge. My clan values honor above all else and will respect your claim to trial by combat.\n\nAs reward, you will be allowed to walk away with your life. Or, you will be dead.", completion = "A great victory over the Burning Blade!\n\nThis new Warlord Azuka Bladefury sounds formidable. We'll have to keep an eye on her and her blademasters.", objectives = "Survive the Burning Blade's trial by combat.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34958] = { id = 34958, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of the Worldbreaker", description = "Looks like we'll soon have another obstacle in our way: that ridiculously large tank that they have pointed at the Dark Portal. The Iron Worldbreaker, I think they call it.\n\nIf I had some documentation on how it might work, then I might be able to figure out how to shut it down. Maybe some o' those machinists and laborers have some documentation on how it works?", progress = "Any luck?", completion = "Mmm... yes... simple enough.\n\n<The dwarf flips through the pages and no longer seems to notice your presence.>", objectives = "Obtain the Worldbreaker Schematics from Blackrock Orcs in the Blackrock Quarry.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34959] = { id = 34959, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreadpiston", description = "The Iron Horde overtook a peaceful draenei outpost without mercy.\n\nThey used a machine they call Dreadpiston to level the town in minutes.\n\nDestroy it.", completion = "They will not use that machine to kill any more draenei. Thank you, {name}.", objectives = "Defeat Dreadpiston.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34960] = { id = 34960, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Land Provides", description = "The icevines of the Shivering Trench have developed a powerful resistance to cold temperatures. Integrating them into the construction materials of the garrison should prove useful.", progress = "Look at you, bein' all resourceful.", completion = "Now this is some handy stuff. This weather has been cutting through our supplies of rope so quick we need something we can use to provide an alternative. Looks like you scored the jackpot.", objectives = "Collect 30 Frozen Plant Matter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34962] = { id = 34962, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar's Plan", description = "We have the Iron Horde backed into a corner now, thanks to you.\n\nIt is almost time to enter the city of Shattrath and repel them.\n\nFirst, we must meet Khadgar and some new allies.", completion = "You have done great work with Durotan, Draka, and Gazlowe.", objectives = "Speak with Khadgar near the gates of Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34963] = { id = 34963, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Khadgar's Plan", description = "Shattrath must not fall into the hands of the Iron Horde. It is time again for me to get my hands bloody.\n\nWe will tell Khadgar we are ready to enter the city and take back what is rightfully ours.", completion = "You have done great work with Maraad, Yrel, and Thaelin.", objectives = "Speak with Khadgar near the gates of Shattrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34964] = { id = 34964, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Farseer Awaits", description = "Your presence has been requested at the Throne of Elements, {name}.\n\nFarseer Drek'Thar heard the call of the furies upon the wind and made the journey to commune with the elements.\n\nThe Farseer has sent word that you are to join him at the Throne of Elements.\n\nGo and see what the elements would have of you.", completion = "Throm-Ka, {name}. All is not right in Nagrand, it is good that you are here.", objectives = "Find Farseer Drek'Thar at the Throne of Elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34965] = { id = 34965, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Called to the Throne", description = "It was not long after I arrived in Nagrand that the voice of Kalandrios called out to me upon the wind.\n\nIt is a great honor to be called to the Throne of Elements, but my heart was heavy sensing the purpose.\n\nThere is dark malaise in the air, it can be felt all around us. It surrounds all life here...enveloping...smothering...\n\nCome, it is time we commune with the furies and lend them our aid. An invisible shadow has been cast upon this valley and it may be up to us to remove it.", progress = "It is time that we communed with the furies regarding the sickness here.", completion = "I fear that this disturbance is more dire than I had anticipated.\n\nWhatever it is...it threatens to unravel the elemental bonds that hold this world together.", objectives = "Commune with the furies at the Throne of Elements.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34966] = { id = 34966, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Doug Test - Daily Repeatable" }
quests[34967] = { id = 34967, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Raided Loot" }
quests[34968] = { id = 34968, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Ice-Covered Supplies" }
quests[34969] = { id = 34969, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Serena Summoned" }
quests[34970] = { id = 34970, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Iron Deck", description = "Now that you have gathered all of the cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Iron Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34971] = { id = 34971, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Way to Travel", description = "Call me cautious but I kept a few flares just in case we needed to evac.\n\nI'm glad that wasn't needed but we could still use the ride back to the arsenal.\n\nAre you ready, <sir/ma'am>?", completion = "The outpost is now fully up and running and we have enough material to outfit an army - your army!", objectives = "Speak to Morketh Bladehowl in Vol'jin's Pride.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34972] = { id = 34972, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Up", objectives = "It took a lot of hard work but we have made a beautiful arsenal here.\n\nSir, I've been able to outfit your soldiers here with new equipment but I'd like to do more.\n\nI'd be deeply honored if you would let me work for you in your main garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34973] = { id = 34973, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Moon Deck", description = "Now that you have gathered all of the cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Moon Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34974] = { id = 34974, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon Visions Deck", description = "Now that you have gathered all of the cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the Visions Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34975] = { id = 34975, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Darkmoon War Deck", description = "Now that you have gathered all of the cards together into a deck, a ninth card mysteriously appears with the same backing as the first eight.   On this card is inscribed, \"Return these cards to the Darkmoon Faire and be rewarded.\"  You have heard that the entrance to this faire appears near Mulgore and Goldshire every month.", objectives = "Return the War Deck to the Darkmoon Faire when it comes to town.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34976] = { id = 34976, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Bombs", description = "The Gordunni have only a single path to their fortress and it is well-defended from a large attack.\n\nThankfully they wont be expecting just the two of us to be attempting to break in.\n\nThis is a great opportunity to take out their defenses and get some target practice for our gunners back at the artillery tower.\n\nTake these smoke grenades and use it to call in an artillery strike on their catapults as we head up.", completion = "Now that we're inside we have much to do.", objectives = "Call artillery strikes on the Gordunni Boulderthrower encampments within Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34977] = { id = 34977, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Recovery", description = "We seem to have arrived at just the right time!\n\nThe Gordunni have been enchanting armaments for the Iron Horde and it looks like they haven't picked up the latest shipment.\n\nWe could put that gear to far better use in our artillery tower! Lets go hunt down their shipping containers. I brought some signal flares that we can use to call in an air pick-up when we've secured the shipment.", completion = "Alright, that should be the last one we need. \n\nIt isn't the same as retaking Shattrath, but knowing the Iron Horde won't be getting these supplies gives me a bit of satisfaction.", objectives = "Recover 6 Iron Horde Shipments.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34978] = { id = 34978, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prized Repossessions", description = "The Gordunni have plagued the people of Shattrath ever since the city was founded. Over time they amassed quite a hoard of weapons they captured from our defenders in raids.\n\nGetting these weapons in the hands of our soldiers would be practical and I personally would like to get them out of the hands of the ogres.\n\nWhile we are in here can you do me a favor and gather up any of those weapons you come across.", progress = "Were you able to find any weapons?", completion = "Thank you, commander. With this a great dishonor on the legacy of Shattrath has been removed.", objectives = "Collect 6 Shattrath Guardian Maces from Gordunni Bashers or Gordunni Cleavers within Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34979] = { id = 34979, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punching Through", description = "To secure the fortress we need to kill Witch Lord Morkurk, but I don't think we should go straight after him.\n\nHis three lieutenants - Vorgorsh, Zulmork, and Cromaug - are all powerful mages, and all of them are fiercely loyal to Morkurk.\n\nI suspect that if we engage the Witch Lord that they will rush to his aid. Let's take them out so that cannot happen.", progress = "We need to make sure those Vizier's are taken care of before we can deal with Morkurk.", completion = "Now with the viziers gone the whole Gordunni enchantment trade with the Iron Horde will come crashing down!\n\nWe can now turn our attention to dealing with Morkurk.", objectives = "Slay Vizier Vorgorsh, Vizier Zulmork, and Vizier Cromaug.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34980] = { id = 34980, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Lord of the Gordunni", description = "Witch Lord Morkurk is the leader of the Gordunni. We need to kill him to secure the jovite for use in our artillery tower.\n\nMorkurk is an accomplished mage so you better be prepared. Here, take the rocket pack and use it if you need to avoid any of his deadly magic.\n\nArchenon poros!", completion = "Fine work commander! Your combat skills are clearly second to none. I am honored to be your armorer!\n\nLet's get back to the outpost so we can take stock of our new inventory. I saved a few flares to call us in a ride back.", objectives = "Defeat Witch Lord Morkurk within Gordal Fortress.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34981] = { id = 34981, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Only Way to Travel", description = "Call me cautious but I kept a few flares just in case we needed to quickly escape.\n\nI'm glad that wasn't needed but we could still use the ride back to the artillery tower.\n\nAre you ready <sir/ma'am>?", completion = "The outpost is now fully up and running and we have enough material to outfit an army - your army!", objectives = "Speak to Miall in Fort Wrynn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34982] = { id = 34982, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armor Up", objectives = "It took a lot of hard work but we have made a beautiful artillery tower here.\n\nSir, I've been able to outfit your soldiers here with new equipment but I'd like to do more.\n\nI'd be deeply honored if you would let me work for you in your main garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34983] = { id = 34983, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Bombs Tracking" }
quests[34984] = { id = 34984, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Supply Recovery Tracking" }
quests[34985] = { id = 34985, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prized Repossessions Tracking" }
quests[34986] = { id = 34986, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Punching Through Tracking" }
quests[34987] = { id = 34987, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Gunpowder Plot", description = "Ey, <pal/lady>! We got an issue, here.\n\nMe ol' pal Thaelin's rigged together this here plunger out of spare Blackrock parts - engineerin' whiz that he is - but we're gonna need some gunpowder if we really want ta' do any damage.", progress = "Don't go doin' anything inappropriate with that gunpowder, now.", completion = "Woo hoo hoo haaaaa!", objectives = "Find a Blackrock Powder Keg and return it to Hansel Heavyhands.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34991] = { id = 34991, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "To the... Rescue?", description = "The Parchment of Dust reads: \"Put the featherless against one another so that our claws remain unsullied!\" How wise the high Ravenspeaker is to foresee this day.\n\nThere is a great beast on the hillside to the west by the name of Stonescale. It has abducted one of the flock and despite our many attempts we have been unable to defeat it. \n\nGo, prove yourself by slaying the beast and rescuing Tillik! Fulfill your destiny in the name of the Raven Mother!", progress = "Tillik's disappearance caused great sadness to the Flock.", completion = "Tillik! Dear friend I'm so glad you have returned! All of the acolytes missed your witty banter after the evening chants.\n\n<Iktis looks back towards you.>\n\nYes, now your great test is done. You have fulfilled the requirements of The Parchment of Dust!", objectives = "Rescue \"Tillik\" from the beast Stonescale in Gnarlwood Pass.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34992] = { id = 34992, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber Mill" }
quests[34993] = { id = 34993, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Joining the Ranks", objectives = "We've had quite the journey in getting your tower up to speed. If it's agreeable to you, I'd like to join your campaign here.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34994] = { id = 34994, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forever Young", description = "All this sitting around is horrible for business.\n\nI have to find a way to recoup some of my lost profits.\n\nThose Draenei females are obsessed with the way their horns look.\n\nI overheard one of them talking about a root that grows in Blademoon Bloom that supposedly reduces horn shedding or something.\n\nI bet I could sell that root to them for a pretty nice profit.\n\nI'll give you a cut if you help me get a supply going.", progress = "Did you find any Youngroot?", completion = "Hmm... How am I going to package this?\n\nI have an idea!\n\n<Beezil writes Youngroot on a label and slaps it onto a bottle of adder oil.>\n\n< He throws the Youngroot in the bushes behind him.>\n\nPerfect!", objectives = "Pick Youngroot for Beezil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34995] = { id = 34995, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Botani Beatdown", description = "Gidwin is doing much better. Thank you, {name}.\n\nI can't believe the draenei have lived alongside those horrible monsters for so long.\n\nMaybe we should show these beasts what happens when you mess with an Azerothian.", completion = "That's what I'm talking about! Great work out there, {name}.", objectives = "Kill 5 Botani.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34996] = { id = 34996, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rotting Riverbeasts", description = "The botani are infecting the local riverbeasts with some kind of strange flesh-eating plant.\n\nI fear this infection could spread to our people.\n\nIf you see any infested riverbeasts, kill the blooming plants that inhabit their bodies... before they kill you.", progress = "We need to stop this infestation.", completion = "This new is disturbing to say the least. I'm shocked the infestation has spread so quickly.", objectives = "Kill 5 Blooming Mandroga.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34997] = { id = 34997, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Slumberbloom", description = "Huh?... Oh my, I appear to have fallen asleep again.\n\nThese slumberblooms are nothing but trouble. One second I'm fighting botani and the next I'm dreaming I'm an elekk dancing with riverbeasts.\n\n*Yawn* We really should do something about all these slumberbloo *Yawn* ... ZZZZzzzzzzzz\n\n<You gather a small handful of pebbles laying by the sleeping draenei.>", objectives = "Use the Gathered Pebbles to pop the Slumberblooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34998] = { id = 34998, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon Watch", description = "By now you must be wondering about all of this curse business. What could distort a majestic arakkoa into... well, into this?\n\n<Reshad drags a crooked hand through the mottled feathers about his face.>\n\nA raven is prepped and waiting to fly you to Talon Watch. There shall your eyes be opened to the origin of this curse.\n\nPresent the Eye of Anzu to Talon Guard Kurekk. He will guide you from there.", progress = "Reshad sent an outsider here? You must be very important... or very dangerous.", completion = "<Kurekk gazes at the orb.>\n\nIs that... what I think it is?\n\nWe must get this to the Talon Altar.", objectives = "Bring the Eye of Anzu to Talon Guard Kurekk in Talon Watch. Speak with Skytalon Meshaal for a flight.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[34999] = { id = 34999, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hatred Undying", description = "The blood of the dead god, Sethe, lingers in the pools here. And with it, his hatred of Rukhmar and Anzu.\n\nSo strong was this hate that it animates the blood even now, eons after he was slain by his fellow gods.\n\nI need the congealed blood that holds those spiteful creatures together.\n\nThere is nothing the Adherents fear more than the power of this curse - what if we could brandish it against them?", progress = "My attempts to bottle the pooled blood have failed. It breaks down and dissipates when it is taken away from Sethe's bones.\n\nBut I have high hopes for this congealed form!", completion = "Excellent, excellent. Go ahead and drop those directly into the cauldron.", objectives = "Gather 15 Congealed Blood of Sethe from Sethekk Holllow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35000] = { id = 35000, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Banished From the Sky", description = "The Adherents have been casting their enemies into the hollow for generations.\n\nThe pools carry Sethe's dying curse, crippling arakkoa with visions of darkness and intense pain. The mind reels, the body writhes, and the wings wither.\n\nMost arakkoa die or go insane. Only the strongest can resist - seek them out and use the Eye of Anzu to help them to their senses.\n\nBeware, for the worshippers of Sethe also prey on these survivors to fill their ranks.", completion = "They have suffered a fate worse than death, but at least they are free.", objectives = "Use the Eye of Anzu on 8 Cursed Arakkoa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35001] = { id = 35001, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gaze of the Raven God", description = "The Sethekk are breeding vile wind serpents from Sethe's blood and bones. With these creatures, they will tear apart the sky.\n\nThe nests are protected by powerful magic, but Anzu's gaze should penetrate them with ease.\n\nLet us visit the nests and destroy them!", completion = "<As the orb meets the altar, the nearby candles flare up.>", objectives = "Use the Eye of Anzu at 4 Wind Serpent Nests.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35002] = { id = 35002, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sons of Sethe", description = "Many years have passed since anyone has been in contact with Anzu. He faded away, as Terokk did, to take refuge in the shadows.\n\nIf we are to coax him back, we should make an offering.\n\nSethe took the sky from us all - it seems fitting to take the wings of his children.", progress = "<A large bowl awaits an offering for the raven god.>", completion = "<Heaping the wings into the bowl, you hear a faint rustling of feathers from somewhere overhead.>", objectives = "Collect 6 Wind Serpent Wings.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35003] = { id = 35003, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritual Severance", description = "I could not defeat this curse, and long ago resigned myself to rest in darkness.\n\nBut the Sethekk are performing dark rituals to draw me back, slowly binding me to Sethe's will. Should they succeed, Sethe would have me draw a dark cloak across the horizon, and bathe the world in his blood.\n\nDisrupt their rituals, so that I may return with my own free will. Then, together, we shall bring an end to Sethe's return.", completion = "Ah... I feel their grasp slipping.\n\nThank you, mortal.", objectives = "Stomp out the three Sethekk Ritual Circles by running over them.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35004] = { id = 35004, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Servants of a Dead God", description = "Even in death, Sethe exerts influence. The Sethekk cult was born of this influence: led by a false king in service of the dead god.\n\nSilence their prophets, for they seek a future of black seas and blighted skies.\n\nDefeat their chosen champions, for they have pledged themselves to a lie.", completion = "Weapons and zealotry do not make one strong.\n\nThey turned to Sethe because they were too weak to face death.", objectives = "Slay 6 Sethekk Prophets and 6 Sethekk Chosen in Sethekk Hollow.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35005] = { id = 35005, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for Battle", description = "There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde.\n\nIt's time to turn this unarmed group of prisoners into an army.", progress = "These prisoners are no less brave than you or I, {name}. Give them a weapon and an ounce of hope and they will fight like the storm.", completion = "Great work, {name}.\n\nDon't put away your weapon yet - now's when the REAL work begins.", objectives = "Obtain 30 Blackrock Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35006] = { id = 35006, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Poison Paralysis", description = "There are others from the caravan that have gone missing.\n\nMy guess is they have been taken into Blademoon Bloom by the botani.\n\nYou have to rescue them, {name}. You are our only hope.\n\nHere, take some of this elixir I just made, chances are you will need it.", completion = "I can never repay you for all you have done here today, {name}.\n\nI am truly in your debt.", objectives = "Rescue the missing travelers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35007] = { id = 35007, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rendezvous with the Ritualists", description = "Our dear brother Sekara went to the Ravenskar with some of the flock to enact the great ritual of purification.\n\nNo one has been sent back to the nest for supplies in the past day; caught up in prayers I suppose.\n\nI would go check on him but I need to make sure the scribe didn't mess up her transcription of my latest sermon. Could you do it? I'll be there in... well, who knows...", completion = "At last, our prayers to the Raven Mother have been answered!", objectives = "Speak to Ravenspeaker Sekara in the Ravenskar.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35009] = { id = 35009, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Call of the Raven Mother", description = "All is now in its place to begin the ritual of calling that will bring the Raven Mother back to the nest.\n\nYou have fulfilled all of the tests we have put before you so it is only fitting that you join with us and participate in the ritual.\n\nSoon the Raven Mother herself will appear before us! Oh my feathers are tingling in excitement!\n\nSpeak to me again when you are ready.", completion = "You have done much to help my little nest of forgotten ones. The poor creatures are not quite sane but with their own kin hunting them I pity their plight.\n\nTheir flying kin, the Adherents you call them, would see the forgotten ones destroyed and my children made into slaves.\n\nThis I must not allow!", objectives = "Help High Ravenspeaker Krikka with the ritual of calling.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35010] = { id = 35010, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The High Ravenspeaker", description = "Yes, I knew you were worthy!\n\nThe Writ of Faith says that great doubt will come in time of crisis but one must put their trust in the Raven Mother and all will be as it should!\n\nCome, come, we must go to the High Ravenspeaker!", completion = "In the whispers of the Raven Mother, blessed she be, it was foretold in the Scroll of Order that upon calling for a sign that we would receive one within thirty minutes or less.\n\nThis is most fortunate, for we have already begun our preparations for her arrival and we have need of your assistance.", objectives = "Locate High Ravenspeaker Krikka", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35011] = { id = 35011, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The False Talon King", description = "Ikiss was once a respected sage among the Adherents, but his search for the truth of Terokk's fall led to his own banishment.\n\nIkiss became obsessed with Terokk, even claiming to be the old hero reborn. He commands the Sethekk, promising untold power in a new age of darkness.\n\nKnow this: Ikiss is no Talon King. Slay the delusional fool, and search him for anything useful. He is known to collect powerful trinkets.", progress = "Have you silenced the false king?", completion = "A bracelet? Interesting... rather plain looking...", objectives = "Retrieve the Scuffed Bangle from Talon King Ikiss.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35012] = { id = 35012, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sethe, the Dead God", description = "The time has come to put an end to Sethe. I killed him before, and with your help I shall do it again.\n\nReady yourself for a fight - the cultists will not stand idly by while we stamp out their god.", completion = "Sethe has died twice, but his curse lives on. It seems we will never be rid of it.", objectives = "Help Anzu defeat Sethe in the Broken Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35013] = { id = 35013, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lithic's Gift", description = "<Kurekk squints at the bangle, rotating it slowly in his claws.>\n\nThere is an inscription on the inside.\n\n\"To my father, may Rukhmar illuminate your path. With love, Lithic.\"\n\nIt cannot be... This is Terokk's bangle! It was a gift from his daughter, he wore it for years until...\n\nWell, we had better return it.\n\nTerokk built a memorial to Lithic not far from Talon Watch. It should rest there.", progress = "Who... are you? Why have you stirred me?", completion = "That bracelet... I made it for father long ago.\n\nBefore the fall...", objectives = "Bring the Scuffed Bangle to Lithic's Rest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35014] = { id = 35014, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blademoon Bloom", description = "We are out of options.\n\nI'm going into the bloom to find out what's going on. I'll meet you inside.\n\nGoodluck, {class}.", completion = "Good, you made it. I need your help.", objectives = "Meet Rangari Arepheon inside Blademoon Bloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35015] = { id = 35015, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gestating Genesaur", description = "This is bad. A genesaur is starting to sprout right here in the bloom.\n\nThis is the first reported case of a genesaur being born in draenor in over three hundred years.\n\nNo wonder the botani have been acting so crazy. They are bringing back bodies to fertilize that monstrosity.\n\nWe have to kill it before it gets any larger. Once fully grown there is no stopping that beast.", progress = "I never thought I would see a genesaur in my lifetime.", completion = "That was close.\n\nIf that genesaur would have grown any larger we would have needed an army to destroy it.\n\nThank you for all your help.", objectives = "Kill the genesaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35016] = { id = 35016, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Basic Skulltaking", description = "My hunters are all dead, you will be my hunting pack now.\n\nFind their bodies and take their skulls.  I will choose which to honor and which to cast aside.  It is our way.\n\nI will go further and see what other skulls may be found here.", progress = "Afraid to get your hands dirty?  They are just bodies now, no need to be scared.", completion = "This red slime covers everything, even the skulls of my hunters!  I'll make a Skulltaker of you yet though, great work!", objectives = "Take the skulls from 5 dead Skulltakers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35017] = { id = 35017, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skulltaker's Revenge", completion = "Hah!  If he was that strong he'd still be alive.  Still it is good you did him honor.  Did you take his skull by any chance?", objectives = "Kill 7 Fungal Lurchers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35018] = { id = 35018, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Felbark" }
quests[35019] = { id = 35019, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Prepare for Battle", description = "There's nowhere to hide up here. We need to keep moving, and to do that, we need to pass right through the heart of the Iron Horde.\n\nIt's time to turn this unarmed group of prisoners into an army.", progress = "These prisoners are no less brave than you or I, {name}. Give them a weapon and an ounce of hope and they will fight like the storm.", completion = "Great work, {name}.\n\nDon't put away your weapon yet - now's when the REAL work begins.", objectives = "Obtain 30 Blackrock Weapons.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35021] = { id = 35021, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Pod", description = "This pod is similar to the ones growing on or near the bodies around here, except this one is pulsating weirdly.  Grulkor might know more about this.", completion = "What's this?  Let me check if it has a skull...", objectives = "Bring the Glowing Red Pod to Grulkor at Crimson Fen.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35022] = { id = 35022, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lighting The Darkness", description = "The spirits of my ancestors have always been drawn to the mountain of Oshu'gun. Now, I too feel this pull deep within my soul...but something is not right.\n\nThe presence that beckons us has grown dark and ominous. It consumes the souls of the dead, the souls of my ancestors, {name}.\n\nSomething must be done.\n\nTake hold of the spirit torch and light the ceremonial pyres in the Ancestral Grounds.\n\nThe flame of the spirit torch upon the pyres will calm the restless spirits being drawn into the void.", completion = "Now that the flame of the spirit torch is upon the pyres, the spirits of my ancestors have been insulated from the call of the void within Oshu'gun.\n\nHowever, more must still be done if the spirits here are to rest peacefully.", objectives = "Use the Spirit Torch to light the Ceremonial Pyres within the Ancestral Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35023] = { id = 35023, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Echoes of the Past", description = "When a spirit is consumed by the void, an echo of the soul is all that is left behind.\n\nNeither in the physical or spiritual sense of the word would these echoes be considered 'alive.' The echo is merely a twisted reverberation of the anguish left behind by the soul as it is consumed.\n\nIf left unchecked, the echoes will lash out against the living and stir the spirits of the dead from their graves.\n\nIn order to restore peace to the Ancestral Grounds, these echoes must be put to rest.", completion = "Do not mourn the twisted echoes of the dead, they are merely the distorted reflections of once noble spirits.\n\nInstead, mourn the loss of those souls consumed by the dark void that grows within Oshu'gun.", objectives = "Slay 8 Tormented Echoes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35024] = { id = 35024, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Golmash Hellscream", description = "Those who die in brutal combat often enter the spirit world in unrest. So it was with Golmash, father of Grommash Hellscream.\n\nCrushed within the jaws of a hulking gronn, Golmash still found the strength to bury his axe Gorehowl deep into the eye of the monster. When they fell, it was the gronn who died first.\n\nSuch is the heroic death that every Warsong dreams of, yet few attain. But Golmash's mighty spirit lingers restlessly, stirring the other spirits into unrest.\n\nPut his mighty soul to rest, {name}.", progress = "Have you brought peace to the spirit of Golmash Hellscream?", completion = "Golmash was a mighty warrior in life.\n\nFew orcs have been as honored by their clans and feared by their enemies as the great Giantslayer... the father of the Hellscream name. With the mighty spirit of Golmash Hellscream finally put to rest, the ancestral grounds may once again be a place of peace and reverence.\n\nYou have our thanks, {name}.", objectives = "Defeat the spirit of Golmash Hellscream.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35025] = { id = 35025, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Have Company", description = "Outsider, I've spotted Iron Horde soldiers nearby.\n\nIt is bold, even for them, to venture into such deadly territory.\n\nIf you do not deal with their presence, they will surely be a threat to your camp.", completion = "Thank you, friend. I am in your debt.\n\nThis arrogant Iron Horde has made a dangerous enemy today.", objectives = "Investigate the Iron Horde camp in Sulfur Basin.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35026] = { id = 35026, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "On the Mend", description = "Nisha will heal.\n\nThis ordeal has taken a toll on her. She needs water and rest.\n\nI will bring her to my camp and make her comfortable.\n\nWill you meet us there with some fresh water?", progress = "<Nisha raises her head.>", completion = "<Nisha laps up the water.>", objectives = "Recover 100 Quenching Waters from Steamfury elementals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35027] = { id = 35027, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Way", description = "The dead ones were the strong ones it seems. The weak ones wander about killing invaders to this marsh.\n\nIt feels... wrong... to kill them, but they are worthless and get in our way. Kill these shambling fools so we can move further into the marsh easily.", progress = "Have you taken care of those walking corpses?", completion = "You take too long. Something calls to us deeper in there. Whatever it is, I will have its skull or die trying.", objectives = "Kill 6 Fungus Covered Shamblers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35028] = { id = 35028, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krikka and Vakora Tracking" }
quests[35029] = { id = 35029, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Secret of the Fungus", description = "It smells here and there are whispers.\n\nI feel there is a connection between the plants and beasts here. Special mushrooms seem to focus the beasts' attention.\n\nGo and get some of these for me. I... need... them.", progress = "Where are my mushrooms?!", completion = "Yes, they smell... wonderful. These will help me find the power of this marsh and take it for my own.", objectives = "Collect 5 Glowing Mushrooms.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35030] = { id = 35030, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Grim Harvest", description = "The larger monsters are the key to my destiny, I can feel it. The pods growing on them are even bigger than the one you brought me earlier.  Get me a few of these, they will be... helpful... soon.", progress = "I need more of those pods!  Many more!", completion = "These will aid me greatly.  I must consume them and take their power.  We are close to the end {name}, I can feel it.", objectives = "Bring Grulkor 3 Spore Pods from the Fungal Stompers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35031] = { id = 35031, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heartfelt Search", completion = "We are so close I can almost touch it!  We will have to go deeper, much deeper!", objectives = "Investigate the strange presence at Crimson Fen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35032] = { id = 35032, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Into Anguish", description = "Rulkan's gift to you, the Fragment of Anguish, will allow you to pass into the fortress unhindered. Go up these stairs to the doorway, then use the fragment to enter the compound.\n\nOnce you are inside, you will find three altars powering the magical barrier around their stronghold.\n\nDestroy these runes, and Yrel and I will be able to join you in finding Ner'zhul.", completion = "<You hear Prophet Velen's voice in your mind.>\n\nGood work, {name}! The barriers are down. We are on our way.", objectives = "Use the Fragment of Anguish at the main doorway. Then destroy the Mark of Darkness, Mark of Shadows, and Mark of Anguish.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35033] = { id = 35033, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Welcome to Gorgrond", description = "Gorgrond is one of the most untamed landscapes in all of Draenor.\n\nOnly the most skilled of rangari venture this deep into the wilds.\n\nIt is their camp we are heading for. If you wish to travel ahead, it can be found down this path and to the right.\n\nMaraad and I shall follow after you momentarily. We still have some logistics to work out before we leave the landing.", progress = "I am a fan of the temple gardens but this place is just too far gone for my tastes.", completion = "You have chosen a very unfortunate time to visit our camp, my friend.", objectives = "Follow the Wildwood Wash to Naielle's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35035] = { id = 35035, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seedbearers of Bad News", description = "When these seedbearers are slain their seeds survive. From them spring new seedbearers, not over years, but hours.\n\nLeaving their remains here would soon cause your camp to be overrun.\n\nBurn them, outsider, if you wish your camp to endure.", completion = "Watch them burn!", objectives = "Burn 5 Ancient Seedbearer corpses.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35036] = { id = 35036, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Is This One of Yours?", description = "I found this one skulking nearby. He claims to be an ally of yours.\n\nIs this true? Or does he cook slowly over my fire?", completion = "That half-orc burned my toes!", objectives = "Talk to Rexxar and vouch for Bony Xuk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35037] = { id = 35037, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bad at Breaking", description = "Screams and growls echo from the canyon below - even more than usual.\n\nI don't dare leave Nisha here alone yet.\n\nWill you investigate those noises, {name}?", completion = "They are enslaving gronn? This is an even bigger problem than it might seem.", objectives = "Search the Iron Horde camp at Crushfang's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35038] = { id = 35038, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "What the Bony Xuk?", description = "Good to see your bones are still intact, {name}. Xuk's too.\n\nWhen you set off into the heart of the canyon, Xuk came to offer my services. Xuk not letting you take all of the skulls!\n\nXuk will share with you powerful spirit magics my clan has passed down for many generations. While Xuk make preparations, you must gather the reagents.\n\nFirst, we'll need crystals from husks of goren corpses. You can find their bodies in the canyon.", progress = "Laughing Skull have some dirty tricks behind our masks.", completion = "Yes... we don't need their bones, but we do need their crystals.", objectives = "Collect 25 Goren Crystals from Longtooth Gorgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35040] = { id = 35040, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Heart of the Fen", description = "If only the trees here weren't screaming at me I could concentrate better. Never mind, they are only trees.\n\nThis spot is used up but now I can feel a much stronger presence deeper in the marsh.  I will go there now and take what is rightfully mine!\n\nThen I will share it... with everyone...", completion = "Grulkor was crazy to think he could harness the power of those mushrooms, but then, most Laughing Skull are crazy.\n\nStill, not a complete waste of time.", objectives = "Follow Grulkor deeper into the Crimson Fen and deal with what comes.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35041] = { id = 35041, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xuk It!", description = "It is done.\n\nWith this enchantment, not only can you roam amongst the goren freely, but you can move as they do.\n\nYour travels through Gorgrond are now made simple. You have safe access to places otherwise impossible to reach.\n\nXuk's ancestors have made it so.", progress = "What has that orc done to you?!", completion = "It is good that you still have your wits about you. You do... have your wits about you?", objectives = "Use the goren disguise to explore locations in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35044] = { id = 35044, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cordana Summon" }
quests[35045] = { id = 35045, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In Ared's Memory", description = "My master has gone on to the Light, but I will continue his work.\n\n<Miall looks to Ared >\n\nShanai ortar, Ared.\n\nI will have his body sent to Auchindoun. For now, show me this artillery tower of yours.", completion = "This is a beautiful and well equipped structure. Thank you for allowing me to work here.\n\nI am positive with this place I can carry on my master's legacy. You will not regret this!", objectives = "Speak to Miall inside of Fort Wrynn in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35047] = { id = 35047, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dropping Bombs Tracking" }
quests[35049] = { id = 35049, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lumber Mill" }
quests[35050] = { id = 35050, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rescue Rangari", description = "Many of our rangari have not been accounted for. It would seem the followers of Iyu have taken captives.\n\nWe will continue to search the area for survivors.\n\nIn the meantime, follow the Wildwood Wash west toward Highpass and look for any signs of our rangari comrades.\n\nOur people are stout and capable survivors. You may find more than you expect. Have them stay near the road and we will follow as soon as this... dwarf creature... has fixed his mechanical vessel.", progress = "It is no small thing for us to welcome so many strangers into our camps. Gorgrond is not the sort of place that breeds trust easily.", completion = "The rangari are stout survivalists. I knew they would not go down without a fight.\n\nThank you, {name}, for your help in this. You have done us a great honor.", objectives = "Find Rangari Rajess, Rangari Kolaan, and Rangari Jonaa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35051] = { id = 35051, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Tower Complete" }
quests[35055] = { id = 35055, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost Mole Machines", description = "Few people know the Blackrock clan better than Dark Iron dwarves.\n\nSo after Tanaan, we sent a bunch of mole machines to Gorgrond to build a listenin' post to keep an eye on them.\n\nMe own mole machine got way off course an' I got separated. It didn't take long to figure out all the other mole machines got off course as well.\n\nAccordin' to the readin's in me tank, a mole machine surfaced somewhere way to the west of here.\n\nMind scoutin' ahead while we get this tank operational?", completion = "Well, that's one down, and about a dozen others to go. We best get a base goin'. Sounds like we might be here a while.", objectives = "Find the Missing Mole Machine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35056] = { id = 35056, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Flag - Horned Skull" }
quests[35057] = { id = 35057, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette XP reward - Frostfire", description = "This quest is a placeholder until Task 67719 is complete." }
quests[35058] = { id = 35058, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mysterious Flask", description = "The liquid swirling around inside the flask clearly has strong alchemical properties, but its nature is beyond your training.\n\nYou have heard that one of the Stonefang refugees at your garrison has some knowledge of the alchemy of Draenor. Perhaps he could tell you more?", completion = "Ah. I see you have found a creation of Draenor alchemy.", objectives = "Speak to Lo'nash at your garrison.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35059] = { id = 35059, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Along the Riverside", description = "Vindicator Yrel has taken most of our forces north. She's establishing a forward base along the Skysong River.\n\nShe'll want to know that we're almost ready to move against Grommashar.\n\nI'm sure she can also use your help dealing with the Warsong orcs at Lok-rath.", completion = "It's good to see you, commander. When I'd heard about your garrison caravan being destroyed....\n\nWell, let's just say that I feared the worst.\n\nWhat word from Telaari Station?", objectives = "Speak with Vindicator Yrel at Yrel's Watch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35060] = { id = 35060, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terms of Surrender", description = "Believe it or not, I have good news: we've already taken Lok-rath.\n\n<The vindicator beams with pride.>\n\nOur soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver.\n\nI saved the honor of accepting his surrender for you. They're waiting for you inside, commander.", completion = "Commander {name}.\n\n\n\nTerms of surrender? Hmm... let me think.", objectives = "Address Uruk Foecleaver at Lok-rath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35061] = { id = 35061, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pride of Lok-rath", description = "You think the Warsong are so easily defeated?\n\n<There's a rasping sound, like rope on metal.>\n\nI'm already tired of you Alliance, and you've just invaded my homeland.\n\n<The sound becomes more pronounced as Uruk Foecleaver looks you straight in the eye.>\n\nThere will be no surrender. The Warsong bow to no one!", completion = "Unfortunate, but I'm glad you made it out of that trap alive.", objectives = "Kill Uruk Foecleaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35062] = { id = 35062, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok-rath is Secured", description = "With their leader dead, the remaining Warsong will be easier to finish.\n\nAs soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar.\n\nIf you're heading back to Telaari Station, would you please inform D'kaan?", completion = "If you hadn't gone to Lok-rath, our forces would have been decimated.\n\nI'm sorry to hear they laid a trap for you. I guess you have a reputation now.", objectives = "Speak with Rangari D'kaan at Telaari Station.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35063] = { id = 35063, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "We Need An Outpost", description = "Commander, we've gathered enough materials to build an outpost that will support our mission against the Iron Horde.\n\nHow shall we proceed?\n\nA lumber yard would be valuable for gathering resources in the dense overgrowth to the south, and in confronting the plant monstrosities that defend it.\n\nOn the other hand, a sparring arena would provide us the brutish forces we'd need to push through the magnaron wastelands to the north.\n\nWhen you're ready, make your choice on the table.", progress = "Buildin' an outpost out here requires a certain kind o' crazy.", completion = "Well, that is one thing ta pick. Tell you what, you get this building up and running at full steam and I'll see if I can't adapt these blueprints to work for the space in your garrison.", objectives = "Use the Drafting Table to craft a Lumber Yard or a Sparring Arena.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35064] = { id = 35064, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparring Arena" }
quests[35065] = { id = 35065, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Harvester Has Come", description = "This is what happens when one stands in the path of a genesaur. And where a genesaur walks, the botani follow.\n\nI saw one entering our shelter cave along the northern side of the camp.\n\nIt is commanding the podlings to gather the corpses of our fallen brethren and must be stopped.\n\nI must tend to our wounded, and gather supplies for our departure.\n\nIf you are serious about being a hero, venture into the cave and slay this botani.", completion = "I dread to think what the botani had intended to do with the corpses of our fallen.", objectives = "Slay Harvester Ommru.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35066] = { id = 35066, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fire Ammonite", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Frostfire Ridge for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Mak'jin wants you to collect 10 Fire Ammonite Eggs from Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35067] = { id = 35067, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence the War Machines", description = "The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Yrel's Watch.\n\nSomeone has to silence those war machines!", completion = "Thank you, commander. I thought we were done for sure.", objectives = "Destroy the 3 Iron Horde War Machines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35068] = { id = 35068, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If They Won't Surrender...", description = "This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar.\n\nIf they won't surrender, we have no choice but to eliminate the Warsong.", completion = "Regrettable, but I understand the pride of the Warsong. I would never surrender.", objectives = "Kill 10 enemy forces at Lok-rath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35069] = { id = 35069, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror of Nagrand", description = "<The body of a fallen soldier lies here. Blood and gore trail back from the corpse to the entrance of the cave just to the north.>\n\n<Judging by the howls and the carnage surrounding the den, something truly terrifying must be in there.>", progress = "Commander. How may I help you?", completion = "That's the beast's collar? I heard its howls all the way over here!", objectives = "Collect Shagor's Collar from Shagor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35070] = { id = 35070, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shut 'er Down", description = "Burrowing native creatures known as \"goren\" have tunneled into our crystal mines. Judging from our experience at the gates, I suspect my own experimental resonance crystal is whipping the native wildlife into a frenzy.\n\nEnter the Elodor Dig to the north and disable the malfunctioning resonance crystal!\n\nBe careful - my earthworkers report that the mine is crawling with those beasts.", completion = "Excellent. I will send in some peacekeepers to quell any remaining problems.\n\nExarch Naielle may be right - perhaps I am too aggressive in adapting our technology to this world. Still, I will never quit. Our civilization must move forward!", objectives = "Disable the Malfunctioning Resonance Crystal in the Elodor Dig.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35071] = { id = 35071, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jawless Skulker", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Gorgrond for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Mak'jin wants you to collect 10 Jawless Skulker Eggs from Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35072] = { id = 35072, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fat Sleeper", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Nagrand for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Mak'jin wants you to collect 10 Fat Sleeper Eggs from Nagrand.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35073] = { id = 35073, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blind Lake Sturgeon", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Shadowmoon Valley for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Mak'jin wants you to collect 10 Blind Lake Sturgeon Eggs from Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35074] = { id = 35074, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blackwater Whiptail", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Talador for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Mak'jin wants you to collect 10 Blackwater Whiptail Eggs from Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35075] = { id = 35075, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Abyssal Gulper Eel", description = "We need to stock the garrison pond with local fish.  I need you to search the waters in Spires of Arak for fish that we can stock up with.  Once you have the fish, you will need to slice them up and look for eggs inside.", progress = "Anything biting?", completion = "These will do nicely, {name}!  Thank you!", objectives = "Mak'jin wants you to collect 10 Abyssal Gulper Eel Eggs from Spires of Arak.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35077] = { id = 35077, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Defungination", description = "Have you seen the fungus out there in the water? It's growing faster than a baby ravasaur from Un'goro, and if we don't get it under control, the Gearworks is gonna be ruined like our last village.\n\nUncle Krixel used to tell me to burn away the red fungus because that's what makes it grow so fast.\n\nYou could help us out by taking a flame blaster and clearing out some of those spores down in the shallows.", completion = "Hey good job out there! I couldn't have done it any better myself.", objectives = "Use the QR58 Flame Blaster to destroy 20 Spore Pustules.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35079] = { id = 35079, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spore-be-Gone", description = "We got an emergency!\n\nA bunch of spore drifters have infested the shore and tore up our Spore-B-Gone turrets.\n\nWe're caught with our armor off here! If we don't get those turrets back online then those spores are going to float right in to town and then we'll have another Pinchwhistle Point on our hands!\n\nWe need to get out there and manually activate them.\n\nWell? Are you in?", completion = "Hey you got the dispensers going again.\n\nNice job pal!", objectives = "Activate 6 Spore-be-Gone Turrets.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35080] = { id = 35080, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Mother Lode", description = "Hey we got ourselves a crisis here! Our zeppelin \"The Mother Lode\" crashed onto the south mountain range.\n\nIt was supposed to only be on an observation mission, what could have happened?\n\nWe got to get down there quick and I'm going to need your help on this.\n\nAre you with me?", completion = "Oh my gosh, this is way worse than I thought it was gonna be. I'm really going to need a hand with getting these survivors out of here.\n\nGood thing I have you on the payroll.", objectives = "Meet up with Kimzee Pinchwhistle at the Wreck of the Mother Lode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35081] = { id = 35081, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing Out Before Cleaning Up", description = "Here's the situation.\n\nWe need to get this salvage operation moving ASAP, but the ship went down right in the middle of the wasp nests.\n\nThe ugly bugs are all over the place, and I can't call my team in here to start work until they're taken care of.\n\nGo kill as many of 'em as you can and I'll cut you in on some of the haul.", progress = "I still see a mess of wasps down there.\n\nWe need to clear those wasps out before I can get the salvage operation started.", completion = "That's how ye do it! As soon as my crew gets here we can start work.\n\nHere's your pay. Thanks for doing the job.", objectives = "Kill 8 Crimsonwing Wasps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35082] = { id = 35082, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Getting the Crew Back Together", description = "Oh wow, the debris is all over the mountainside! The survivors won't make it if we don't do something quick. They need healing NOW!\n\nHere, take my bandages and go patch them up.", completion = "Good work, {name}.\n\nOnce Gazwitz gets his team up here we can get the crewmen back to the Gearworks.", objectives = "Revive 6 Injured Crewmen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35083] = { id = 35083, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Disrupt the Rituals", description = "No longer do the Warsong seek to be one with the elements; instead they abuse their power by using it to channel the darkness of the void.\n\nI will not tolerate these rituals to continue. Locate the ritual totems the Warsong use to channel the void and destroy them.\n\nThe gift of the elements was not given to the orcs only to be defiled and used as a plaything.", progress = "Have you destroyed the ritual totems?", completion = "Dark shamanism is a dangerous practice, {name}.\n\nIt is true that the void can be a source of terrible power, but it is the kind of power that comes at a price.\n\nThese woods are safer now that you have put an end to the rituals.", objectives = "Destroy the Ritual Totems.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35084] = { id = 35084, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence the Call", description = "The Warsong clan, in their lust for dominance, have turned to the darkness of the void for power. Dark shamanism is a loathsome, dangerous practice that abuses the elemental gift I have bestowed upon them.\n\nThere is one among the Warsong that calls out the loudest to the void, an elder shaman named Kuhlrath. Slay him and the rest of his dark shaman.\n\nI will not allow the Warsong to abuse the elements and desecrate tradition.", progress = "Have you put an end to the Warsong ritualists?", completion = "The gift of shamanism is not one to be taken lightly. When the gift is abused, the elements will rise up in indignation and smite the shaman.", objectives = "Slay Kuhlrath and 10 Warsong shaman.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35085] = { id = 35085, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Through the Nether", description = "The rituals have been disrupted, yet the nether beacons still glow with power....\n\nThis can only mean that the beacons are powered from within the Twisting Nether itself!\n\nThe connection to the void must be severed! There is but one way to accomplish this; you must slay the void creature that maintains the connection with our world.\n\nLay your hands upon a beacon and travel into the Twisting Nether. When you have arrived on the other side, locate a Shamanstone and use it to contact me.", progress = "The veil between dimensions is thin. Do you hear my words through the shaman stone?", completion = "The Shamanstone appears to be working, even from within the Twisting Nether.\n\nThere is much that needs to be done, {name}. The monsters of the void are gathering upon Oshu'gun and must be stopped, else they invade our realm.", objectives = "Use a Void Beacon to travel to the Twisting Nether.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35086] = { id = 35086, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Void March", description = "Hidden behind the veil of the Twisting Nether, the abominations of the void march upon Oshu'gun. The great void growing deep within the mountain has drawn them like moths to a flame.\n\nWave upon wave, the creatures of the void march upon the mountain and sacrifice themselves to Invalidus. The void lord Invalidus cannot be allowed to feast upon the other void creatures, else it will become too powerful to stop.", completion = "The void lord must be stopped. Thanks to your effort, the tide of void creatures has waned... but if we are to defeat Invalidus we must act swiftly.", objectives = "Destroy 10 Void Terrors and 15 Void Tendrils.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35087] = { id = 35087, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Nether Approaches", description = "By connecting with the Twisting Nether, the Warsong shaman have created a ripple effect that they could not have anticipated.\n\nLook around and you will see countless portals beginning to open, signs that the Twisting Nether seeks to connect to Draenor.\n\nShould these portals successfully open, the path will be clear for all manner of demons and void creatures to rampage across this valley.", completion = "If those portals were to fully expand and open, the path would have been clear for the horrors of the Twisting Nether to march upon Nagrand.\n\nThe Warsong have been careless in their mad pursuit of power and glory.", objectives = "Collapse 6 Void Portals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35088] = { id = 35088, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shadow of the Void", description = "The moment has come to take on the void lord. Invalidus grows more powerful by the minute, so you must move with haste if you are to defeat the monster.\n\nAt each of the Warsong ritual locations there is a void crystal; these crystals are used to channel the energy of the void from within the Twisting Nether.\n\nDisturb the crystal, and Invalidus will sense your presence below.\n\nBe ready, as soon as the crystal is disturbed, Invalidus will waste no time hunting you down.", progress = "Have you defeated Invalidus?", completion = "With Invalidus destroyed and the Warsong rituals halted, the threat of the Twisting Nether has subsided.", objectives = "Summon and defeat Invalidus.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35089] = { id = 35089, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Skimming Off the Top", description = "That flying machine is our ticket out of here but its fuel tank is bone dry!\n\nWe're right next to the oil fields but with the infected out there we don't have time to run a line up here so we need to improvise.\n\nThe oil creatures moving next to the pumps out there are full of a highly potent mixture that I can drop right into the tank. Grab some of that oil for me and we'll be one step closer to getting out of here.", progress = "Do ya have that oil for me yet?", completion = "Yea that's the stuff!\n\nNow I just need to connect the spark plugs and patch up a few holes and it'll be nearly in working order!", objectives = "Collect 4 Volatile Oil.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35090] = { id = 35090, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Right Parts for the Job", description = "Uncle Krixel's a tough one but he won't be going anywhere on foot with his leg broken.\n\nHe has a flying machine he brought from Azeroth that can fly us out of here. Problem is, the engine's busted.\n\nI'll need some parts to fix the thing. My car's wasted but those broken shredders just outside of town should have what we need. We don't have time to break them down by hand so just use this rocket launcher and blow 'em apart. Anything that survives the blast should be strong enough to use on the engine.", progress = "Got any parts for me?", completion = "Great work {name}!\n\nGive me some time and I'll have this thing ready to roll out!", objectives = "Use the G-14 Buster Rocket near Broken Shredders to retrieve Serviceable Gears.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35091] = { id = 35091, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sporicide", description = "It's revolting, absolutely disgusting, infuriating even!\n\nI'm talking about seeing those spore creatures walking around Pinchwhistle Point.\n\nWhile I'm working on the machine here how about you go out and kill off some of those spore creatures? I'll feel a bit better knowing there are less of those things moving around.", progress = "Did you put down those spore creatures yet?", completion = "Thank you, {name}.\n\nThe less of those spore beasts around the safer we all are.", objectives = "Kill 6 Spore Shamblers in Pinchwhistle Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35092] = { id = 35092, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Portal's Power", description = "The mana bombs were not enough. This was always a risk.\n\nThis is unfortunate.\n\nGul'dan, the orc beneath these grates, says he can shut down this portal. Find a way in there, and do whatever it takes to slow this portal down.\n\n<The archmage's eyes lock with yours.>\n\nWHATEVER IT TAKES.", sourceObjective = "Speak with Gul'dan underneath the Dark Portal.", sourceObjectiveStatus = "unverified-source-field" }
quests[35093] = { id = 35093, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Side of the Moon", description = "Yrel and I have located Warlord Ner'zhul. He is meeting with Grommash Hellscream atop the highest altar overlooking Anguish Fortress.\n\nMeet us there. We must stop him.", progress = "Ner'zhul will pay for what he has done.", completion = "We saved everyone we could, {name}. We were too late for the others... including my sister.\n\nProphet Velen is right. When it is asked of us, we ALL must fight. I promise this: I will never again let my loved ones suffer.\n\nNer'zhul is close to calling down the Dark Star. We are the only ones who can stop him.", objectives = "Find Ner'zhul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35094] = { id = 35094, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Deal with Darkness", description = "<With Gul'dan gone, the Dark Portal is disabled, and the threat to Azeroth is suspended.>", sourceObjective = "Report back to Archmage Khadgar atop the Dark Portal.", sourceObjectiveStatus = "unverified-source-field" }
quests[35095] = { id = 35095, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Along the Riverside", description = "Durotan has taken most of our forces west. He's establishing a forward base along the Skysong River.\n\nHe'll want to know that we're almost ready to move against Grommashar.\n\nI'm sure he'll also appreciate your help dealing with the Warsong orcs at Lok-rath.", completion = "It's good to see you, commander. When I'd heard about your garrison caravan being destroyed....\n\nWell, let's just say that I feared the worst.\n\nWhat word from Wor'var?", objectives = "Speak with Durotan at Riverside Post.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35096] = { id = 35096, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terms of Surrender", description = "I have good news, commander: we've already taken Lok-rath.\n\n<The warchief grins.>\n\nThe Horde's soldiers have captured most of the Warsong, including their leader, Uruk Foecleaver.\n\nI saved the honor of accepting his surrender for you. They're waiting for you inside, commander.", completion = "Commander {name}.\n\n\n\nTerms of surrender? Hmm... let me think.", objectives = "Address Uruk Foecleaver at Lok-rath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35097] = { id = 35097, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pride of Lok-rath", description = "You think the Warsong are so easily defeated?\n\n<There's a rasping sound, like rope on metal.>\n\nI'm already tired of you Horde, and you've just invaded my homeland.\n\n<The sound becomes more pronounced as Uruk Foecleaver looks you straight in the eye.>\n\nThere will be no surrender. The Warsong bow to no one!", completion = "Unfortunate, but you made it out of the trap alive and Lok-rath is dealt with.", objectives = "Kill Uruk Foecleaver.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35098] = { id = 35098, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lok-rath is Secured", description = "With their leader dead, the remaining Warsong will be easy pickings.\n\nAs soon as that's done, I'll pull our soldiers out of Lok-rath and head for Grommashar.\n\nIf you're heading back to Wor'var, inform Thrall that we'll be ready soon.", completion = "If you hadn't gone to Lok-rath, our forces would have been decimated.\n\nI'm sorry to hear they laid a trap you. You have a reputation now.", objectives = "Speak with Thrall at Wor'var.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35099] = { id = 35099, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silence the War Machines", description = "The Iron Horde supplied Lok-rath with war machines from Ironfist Harbor. It won't take long for them to level Riverside Post.\n\nSomeone has to silence those war machines!", completion = "Thank you, commander. I thought we were done for sure.", objectives = "Destroy the 3 Iron Horde War Machines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35100] = { id = 35100, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If They Won't Surrender...", description = "This is the backbone of the army we intend to send against Garrosh Hellscream and Grommashar.\n\nIf they won't surrender, we have no choice but to eliminate the Warsong.", completion = "Regrettable, but I understand the pride of the Warsong. I would never surrender.", objectives = "Kill 10 enemy forces at Lok-rath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35101] = { id = 35101, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Terror of Nagrand", description = "<The body of a fallen soldier lies here. Blood and gore trail back from the corpse to the entrance of the cave just to the north.>\n\n<Judging by the howls and the carnage surrounding the den, something truly terrifying must be in there.>", progress = "Commander. How may I help you?", completion = "That's the beast's collar? I heard its howls all the way over here!", objectives = "Collect Shagor's Collar from Shagor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35102] = { id = 35102, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unleashed Steel", description = "Thank you... boss.\n\nI won't let you down! I didn't even try to sneak one of those low quality blades here that one of your peons placed right next to the cage. Which by the way was a pretty terrible idea and that thing should be moved before you get anyone less honorable in here.\n\nEnough talk, lets check this place out!", completion = "We have a lot of basic arms here but I'll get them improved in no time.\n\nThanks for giving me this chance.", objectives = "Speak to Morketh Bladehowl inside of Vol'jin's Pride in Talador.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35103] = { id = 35103, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Alchemist", description = "I know a little about alchemy from my cousin Kadar. She is the alchemist at Stonefang Outpost. If you wish to learn more, she is the one with whom to speak.\n\nI only hope she has survived the attack.", completion = "My apprentice... Inside... (She dies in your arms.)", objectives = "Find Kadar at the Boneslag.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35104] = { id = 35104, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Apprentice", description = "Kadar's last words... Is there someone still inside the hut?", progress = "She is unconscious and pinned under heavy, broken shelves, but she is still breathing.", completion = "What... happened? Where is my master?", objectives = "Remove the rubble and speak with Ang'kra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35105] = { id = 35105, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Honor and Remember", description = "So she is dead.\n\nShe took me in when I had no one. She taught me everything I know. She gave me everything I have. And now, she is dead.\n\nI owe you my life, stranger, but I wish you had saved hers, not mine. Please, help me bury her.", objectives = "Gather Frostweed and Fireweed seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35106] = { id = 35106, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Avenge and Reclaim", description = "I will avenge my master and retrieve her life's work. Honor demands it. My heart yearns for it. If I die trying, so be it. The murderer will pay.", progress = "The murderer will pay.", completion = "My heart is furious with you for stealing my kill, but my mind knows that I did not have the strength to avenge my master myself. I will forgive you, if you allow me to pay my debt of honor.", objectives = "Slay Kadar's killer and retrieve the book.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35107] = { id = 35107, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Book of Alchemical Secrets", description = "The writing in the leather-bound tome is undecipherable, except for the inscription inside the cover: \"For my daughter, Ang'kra.\"", objectives = "Return the Book of Alchemical Secrets to Ang'kra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35128] = { id = 35128, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fair Warning", description = "The ogron here are far from brilliant, but they are more intelligent than the gronn. They're large, and even stronger than they look.\n\nTheir leader, Borogahn, is especially formidable. Despite several fights, I have not yet managed to kill him.\n\nHeed my words, friend. Take caution as you explore their lair.\n\nNisha is ready to move. Ask her to take you to the mouth of the cave, and I'm sure she would be happy to.", completion = "Most people cannot handle ogron in single combat.", objectives = "Kill 8 Ogron Spinecrushers and Borogahn.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35129] = { id = 35129, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leave Every Soldier Behind", description = "Hmmm.\n\nThe ogron possess something of value to the Iron Horde. I'm sure they're unaware, likely just bored and in  need of something to torture.\n\nI'd be inclined to just let them be, it's a fate they deserve. But we can't afford not to follow up on this clue. With any luck, it will help us stop the Iron Horde from turning Gorgrond's most fearsome creatures into weapons.\n\nTry to find this Corporal Thukmar and his notes. We'll meet you there.", progress = "Again you've done well, friend.", completion = "We have the notes. Let us see what they reveal about our enemy's strategy.", objectives = "Find Corporal Thukmar and recover his intel.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35136] = { id = 35136, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chains of Iron", description = "The artifact we seek is within our grasp.\n\nBe prepared for a fight. If they truly have learned how to control gronn, this may be more difficult than I anticipated.\n\nI will join you in this battle as soon as you arrive.", progress = "The artifact is yours, and is well earned.", completion = "Good work, {name}. We can use this artifact against the Iron Horde when the time is right.", objectives = "Defeat Captain Brak and find the Heart of the Magnaron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35137] = { id = 35137, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparring Arena", description = "We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight.\n\nWe will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond, simply call us.\n\nYou may wish to warn Rangari Jonaa of our coming.", completion = "Now that we have the trainers, we can start training your forces to do something other than chop lumber. Heh heh.", objectives = "Speak with Rangari Jonaa at Highpass in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35139] = { id = 35139, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eye in the Sky", description = "The notes you recovered tell of a device capable of subjugating even a magnaron.\n\nAncient legends speak of such artifacts, crafted by the worldbuilders to keep these creatures in check. I had discounted them as silly stories, but if they are true...\n\n{name}, Draenor is doomed.\n\nNo army will be able to stop them if they harness this power. We must stop them or die trying.\n\nHere, I shall bind our sight to Nisha and hope she can locate this artifact.", progress = "We are in luck! The artifact is still within reach.", completion = "Good. We know where we must go to acquire the artifact.", objectives = "Speak to Nisha.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35140] = { id = 35140, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "THAELIN!", description = "That little...!\n\n<Yrel tries to maintain her composure.>\n\nThaelin Darkanvil sent us a shipment. It was supposed to be engineering parts.\n\nInstead, when we just opened one of the crates, out popped a baby goren. Do you know how destructive those things are?\n\nAnd, of course, the one baby immediately set about letting all the other ones loose.\n\nWant to help me get some revenge?", progress = "Did you round them all up?", completion = "Outstanding.\n\n<Vindicator Yrel beckons you closer so that the two of you can conspire.>", objectives = "Capture 15 Baby Goren.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35141] = { id = 35141, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Carrier Has Arrived", description = "We're going to get some payback on that little stinker.\n\nPut the baby goren into one of those carriers and then make a special delivery to Thaelin.", completion = "Wait a minute, {name}... let's be reasonable. I can hear what's in that carrier.\n\nIt was just a harmless prank.\n\nDon't do it, please!\n\nStop!\n\nDon't open that carrier!", objectives = "Deliver the Baby Goren Carrier to Thaelin Darkanvil at Telaari Station.\n\nProvided item:", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35142] = { id = 35142, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Goren Invasion!", description = "The earth quakes beneath us, Commander. Our scouts are not returning. I can feel an attack creeping up on us, but from where?", progress = "We must hold the line!", completion = "The peons will clean this mess, Commander. Rubble and holes everywhere. The rest of us will look for hiding goren so that we may apologize to them for butchering their warleader.", objectives = "Repel the goren invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35143] = { id = 35143, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blood of the Burning Blade", description = "Hallvalor is the ancestral home of my clan, the Burning Blade. When the new warlord and his family came to power, I was exiled for being a half-breed.\n\nI want justice.\n\nI suspect you won't mind killing along the way. Not that you'll have any choice.", completion = "A great victory over the Burning Blade!\n\nThis Flamebender Ka'graz sounds formidable. We shall have to keep an eye on her and her blademasters.", objectives = "Kill 15 Burning Blade forces at Hallvalor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35144] = { id = 35144, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Binding", description = "Even as we speak, the pale within Shadowfall Canyon are enslaving the elements to their will. Many elemental spirits have already been enthralled, and more will follow.\n\nThe pale must be stopped and the elementals they enslave set free.\n\nJourney into Shadowfall Canyon and set free those elemental spirits which are not fully enthralled by the pale. As for the elementals already enslaved by the pale, the only mercy we can give them now is to release their bonds through death.", progress = "Have you freed the elemental spirits of Shadowfall Canyon from the dark bonds of the pale?", completion = "The pale have been taught by Cho'gall to enslave the elemental spirits of this land. When an elemental is enthralled in this manner, it cannot be reversed even by a Farseer such as myself.", objectives = "Free 10 elemental spirits.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35145] = { id = 35145, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Pale Threat", description = "The Pale are wretched creatures that hide beneath the ground, ever plotting against those who dwell upon the surface. They stalk the Underpale, a twisted and dark cavern beneath Oshu'gun.\n\nIf we are to succeed in stopping Cho'gall we must fight our way through their ranks beneath the earth.\n\nMake your way into the cavern, slay the vile creatures within and take out the Pale leader... the one known as Greyseer.", completion = "I have encountered evil in many places, {name}. Even deep within my own soul, I have seen dark shadows of what could be.\n\nHowever, the evil within the hearts of the Pale defies explanation. It is dark, loathing, and miserable in a way I have never encountered.", objectives = "Kill Greyseer and 6 Pale orcs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35146] = { id = 35146, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Good Doctor", description = "Our expedition biologist has been kidnapped by podlings!\n\nWe came to Nagrand to explore, to slay the mightiest of beasts, and test our mettle alongside the great Hemet Nesingwary.\n\nAs soon as we arrived, Hemet's hunting prowess was needed to combat the Warsong. Rather than sit around twiddling our thumbs, we decided to continue the expedition!\n\nWe were exploring Spiteleaf Thicket when podlings ambushed us! In the chaos, Dr. Hadley Ricard was taken captive.\n\nPlease, we can't just leave him there!", completion = "Your timely arrival to rescue me from the podlings was most appreciated!\n\nThis research station has seen better days... my equipment and belongings were damaged in the ambush.\n\nHowever, with your aid, I'm sure we'll be up and running again in no time!", objectives = "Rescue Dr. Hadley Ricard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35147] = { id = 35147, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fragments of the Past", progress = "What these ogres see as junk, we see as money!", completion = "<Sallee Silverclamp examines the fragments you've retrieved>\n\nThese will do nicely! Great work, kiddo!" }
quests[35148] = { id = 35148, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Overwatch", description = "Ya know, we sent a couple o' scouts ta check out those big, smelly, 'civilized' ogres at Mar'gok's Overwatch.\n\nHaven't heard from 'em in a bit. Matter o' fact, not since I saved yer bacon up at Telaar.\n\nHave some time ta ride over there and check up on 'em, <boyo/girly>?", completion = "I'm afraid we have some trouble.", objectives = "Locate Rangari Eleena at Mar'gok's Overwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35149] = { id = 35149, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sparring Arena" }
quests[35150] = { id = 35150, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trouble at the Overwatch", description = "Yesterday, I sent two of my best scouts to spy on the ogres at Mar'gok's Overwatch.\n\nI haven't heard back from them.\n\n{name}, would you do me the honor of checking on them? I'm sure it's nothing; the Overwatch is a large fortification.\n\nI'd feel better knowing they're okay.", completion = "I'm honored you're here to help, wolf-brother. Things here are worse than we thought.", objectives = "Find Akrosh at Mar'gok's Overwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35151] = { id = 35151, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Base, Your Choice", description = "You have already constructed an impressive garrison in Frostfire. I believe I should defer this next choice to you.\n\nOne region of Gorgrond is rich in resources. A lumber mill could help us make the most of them.\n\nAnother region harbors hardened gladiators. A sparring arena would help persuade them to fight for our cause.\n\nEither path will strengthen us as we seek to find and weaken the Iron Horde.\n\nWhich do you choose, Commander?", completion = "A fine choice. It will need more work before such a structure could be built in your garrison, but this is a start.", objectives = "Choose to construct either a Lumber Mill or a Sparring Arena at Beastwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35152] = { id = 35152, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Sparring Arena", description = "We owe you our freedom, and more. I have spoken to the others, we are willing to return with you to your garrison and teach those pitiful creatures you call \"soldiers\" how to properly fight.\n\nWe will also do our best to impart our knowledge to you, Commander. Should you have need of us when in the wilds of Gorgrond, simply call us.\n\nYou may wish to warn Limbflayer of our coming.", completion = "Kash'drakor is coming here?! Ha! I once saw him cut through a dozen Laughing Skulls because they had his son.\n\nHe is the purist expression of destruction.", objectives = "Speak with Limbflayer at Beastwatch in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35153] = { id = 35153, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Fungal Praetorian" }
quests[35154] = { id = 35154, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Things Are Not Goren Our Way", description = "The abandoned mine shaft has been overrun with goren!  They seem to be responding to commands from a big one further down in the mine.  If you can take him out, the rest will probably retreat.\n\nOnce you have those goren cleared out, we can get that mine up and working!", progress = "Were you able to take out the leader?", completion = "Nice job, {name}! Let's get this mining operation started!", objectives = "Kill Stonetooth in the Garrison Mine.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35155] = { id = 35155, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obliterating Ogres", description = "We got more of those magic tossing ogres here which is never a good thing.\n\nThese new ogres are especially bossy and have increased work being done here.\n\nDo you know what stops ogres from working hard? Dying.\n\nKill some ogres here and get this camp back to its normal boring self.", completion = "Great! They are pretty scared now. Its hard to do research when you are afraid of being stabbed in the back at any time!", objectives = "Kill 15 ogres at Mar'gok's Overwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35156] = { id = 35156, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Removing the Paper Trail", description = "This box is filled with writings and diagrams that oddly resemble research into the nullification of magic.  It would be best to ruin these efforts by destroying any research found.", progress = "Hey, do you smell smoke?", completion = "Burning magical paper smells pretty bad!  Good thinking {name}, keeping these ogres dumb is a solid plan!", objectives = "Destroy 8 Boxes of Ogre Research at Mar'gok's Overwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35157] = { id = 35157, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Obtaining Ogre Offensive Orders", description = "The upper bluff must be really important to the ogres. Two fancy looking ogre mages came down from there and starting ordering all the others around.\n\nGo get those orders and meet up with my scout Dalgorsh on the upper bluff. They will be more useful to him up there.", progress = "Don't forget! Get the orders and take 'em to Dalgorsh further in.", completion = "Finally some help! I barely got out alive!\n\nYou have some ogre orders? Let me see...\n\nWell that's not good news.", objectives = "Collect Crulgorosh's Orders and Thulgork's Orders at Mar'gok's Overwatch.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35158] = { id = 35158, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reglakk's Research", description = "Okay so these orders say Reglakk is in charge of something called Breaker research, which makes super powerful ogres. I don't know about you but that sounds bad.\n\nI'm pretty hurt, do you think you can go up there alone and make Reglakk rethink his research?", completion = "We stopped him for the time being, but I think we'll have to come up with a more permanent solution. No doubt he's back in Highmaul plotting new versions of Breakers.\n\nI think a visit to ogre capital is far overdue.", objectives = "Stop Grand Magister Reglakk's research.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35159] = { id = 35159, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Removing the Reinforcements", completion = "Good, hopefully they will give up on making a portal here.", objectives = "Destroy the Portal to Highmaul.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35161] = { id = 35161, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette XP reward - Talador", description = "This quest is a placeholder until Task 67719 is complete." }
quests[35162] = { id = 35162, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Treasure: Grovestrider Nest" }
quests[35166] = { id = 35166, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ship Salvage", description = "Commander, we are running low on supplies.\n\nMaybe we can salvage materials from that ship you arrived on?\n\nAt the rate folks are coming through the portal we are going to be out of everything by sundown... or moondown?\n\nI'm still getting used to this place.", progress = "Supplies are getting really low, commander.", completion = "Wow... with all these supplies, we should be back on track.\n\nWe are blessed to have you protecting us, commander.", objectives = "Collect 15 crates of Drudgeboat Salvage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35167] = { id = 35167, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lost in Nagrand", description = "Hey, <mister/lady>, could you help me?\n\nThere's this girl I know. Her name's Olgra. Her and her parents went back to Wor'var yesterday. Only, they never got there and no one's seen them.\n\nIf you're heading back out, would you look for her?\n\nShe's kinda my girlfriend.", completion = "Skytooth! My mama and papa....\n\n<The little girl continues to cry over the corpses of her family.>", objectives = "Find Mankrik's girlfriend, Olgra.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35168] = { id = 35168, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your First Blacksmithing Work Order", description = "Now that the forge is complete, we can start producing truesteel ingots for you. When you have the ingredients, please speak with my assistant to start the first work order.", progress = "Yes?", completion = "Let me unpack that for you.\n\nI should let you know - while we managed to expedite this one, future work orders will take longer.", objectives = "Start and collect your first Blacksmithing work order at the Forge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35169] = { id = 35169, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Justice for Thrall", description = "The time has come, commander. You've dealt with all of the Warsong's allies and holdings.\n\nOur troops are massing at the gates of Grommashar. The rangari have reliable intel that Garrosh is holed up inside the Warsong fortress.\n\nAll of our efforts have led to this moment. Let's take out Garrosh.", completion = "It's over. The Warsong are broken. Garrosh Hellscream is finally dead.\n\nSomehow, I sense it's only a matter of time before Grommash seeks vengeance.", objectives = "Speak with Vindicator Yrel at the Gates of Grommashar and lead the assault on the Warsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35170] = { id = 35170, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Consumed by Vengeance", description = "They... they came out of nowhere. From that direction.\n\n<The young girl points vaguely west through her tears.>\n\nThey were on their nasty wolves.\n\nPlease, commander, my family's honor is at stake. Will you get vengeance for me?", completion = "Thank you, commander. You really are the greatest {class} like everyone says!", objectives = "Kill Worgskin the Savage.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35171] = { id = 35171, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "And Justice for Thrall", description = "The time has come, commander. You've dealt with all of the Warsong's allies and holdings.\n\nOur troops are massing at the gates of Grommashar. The shadow hunters have reliable intel that Garrosh is holed up inside the Warsong fortress.\n\nAll of our efforts have led to this moment. Let's put an end to this once and for all.", completion = "It's over. The Warsong are broken. Garrosh Hellscream is finally dead.\n\nIt's just a matter of time before Grommash seeks vengeance.", objectives = "Speak with Durotan at the Gates of Grommashar and lead the assault on the Warsong.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35172] = { id = 35172, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Your Second Blacksmithing Work Order", description = "Place another work order with my assistant. Once it is complete, we will leave it out here for you to collect.", completion = "We look forward to serving you again.", objectives = "Place a work order, then collect it once it completes. \n\nProgress can be monitored through the Garrison Report pane accessible through the button on your minimap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35174] = { id = 35174, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pale Moonlight", description = "We are getting strange reports of an orc attack on a nearby draenei settlement called Eventide Landing.\n\nI'm hearing these particular orcs are unlike any we have encountered before.\n\nThey seem... sickly, and are pale in color.\n\nThe locals could use our help, commander. This seems like the perfect opportunity to test our garrison's capabilities.", progress = "Did you see the pale orcs, commander?", completion = "This is unnerving to say the least.\n\nThose things must have come from underground.\n\nHopefully we have seen the last of them.", objectives = "Kill Gnaw Bloodseeker and 8 Pale Devourers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35176] = { id = 35176, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keeping it Together", description = "So much work to do... I don't even know where to start.\n\nMaking sure this garrison is operational is not an easy task.\n\nShelly still hasn't reported back to me, my assistant Brightstone and her crew are who knows where, ugh... I'm so caught up I haven't even had time to check our cache for resources.\n\nIf I were a mage, do you think I could use mirror images to do all of this at once?", progress = "Can we speak a little later, Sir? I don't really have time to talk at the moment.", completion = "You did what? You are a life saver, commander.\n\nWith those tasks out of the way my job will be much easier.", objectives = "Speak with Shelly, find Assistant Brightstone, and check the Garrison Cache.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35185] = { id = 35185, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Sargerei", description = "Greetings, {name}.\n\nArchmage Khadgar wishes you to hear an important message.\n\nThe draenei suffered a great betrayal when one of their leaders, Exarch Othaar, revealed himself to be working with the Legion.\n\nIn the hills above Shadowmoon Valley, Othaar, who now goes by the name Socrethar, gathers new recruits to his cause.\n\nArchmage Modera is in charge of this covert operation, which we need your help carrying out.\n\nMeet her in the field, and she will give you the details.", completion = "Greetings, {class}. Khadgar told me to expect you.", objectives = "Speak to Archmage Modera at Socrethar's Rise in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35186] = { id = 35186, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Campaign: The Sargerei", description = "Greetings, {name}.\n\nArchmage Khadgar wishes you to hear an important message.\n\nThe draenei suffered a great betrayal when one of their leaders, Exarch Othaar, revealed himself to be working with the Legion.\n\nIn the hills above Shadowmoon Valley, Othaar, who now goes by the name Socrethar, gathers new recruits to his cause.\n\nArchmage Modera is in charge of this covert operation, which we need your help carrying out.\n\nMeet her in the field, and she will give you the details.", completion = "Greetings, {class}. Khadgar told me to expect you.", objectives = "Speak to Bron Skyhorn for a ride to Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35187] = { id = 35187, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Infiltrating the Sargerei", description = "One of my men has already infiltrated the Sargerei's ranks, but I need you to help him.\n\nIn order to protect his cover, you will need to disguise yourself as one of the enemy.\n\nKill Sargerei until you collect a cowl, robe, and slippers to create a disguise.\n\nAfter donning the disguise, introduce yourself to Soulbinder Zamaya as a new student, then tell Anchorite Laanda that 'the rain falls on Shadowmoon.'\n\nThe secret phrase will identify yourself as an ally.", progress = "Yes, initiate?", completion = "Welcome, my friend. I have managed to earn a bit of favor with the Sargerei, but they still guard their secrets closely.\n\nOnly the strongest will be accepted in the ranks of the Sargerei.\n\nSoulpriest Zamaya is the leader of our operations here. To secure our objectives, you must first win her trust.", objectives = "Collect a Sargerei Robe, Sargerei Cowl, and Sargerei Slippers to create a Sargerei Disguise. Don the disguise, then speak to Soulbinder Zamaya and Anchorite Laanda.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35188] = { id = 35188, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pesky Podlings", description = "Ah, initiate. Are you ready for your first task?\n\nThe woods to the south are filled with pesky podlings. The filthy things dig up our farms, steal supplies, and prey on unwitting trainees.\n\nThey are disgusting, horrible creatures which need to be eliminated.\n\n<Zamaya gives you a skeptical look.>\n\nI will require their spears as proof that you finished this task.", progress = "Those filthy creatures don't deserve to live.", completion = "I expect no less from an initiate.", objectives = "Collect 8 Wooden Spears.\n\nIf you lose your disguise, kill Sargerei enemies to collect a Sargerei Cowl, Sargerei Robe, and Sargerei Slippers to create a Sargerei Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35189] = { id = 35189, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Word of Socrethar", description = "The Sargerei follow Socrethar zealously. From what I can gather, he is a persuasive and compelling leader.\n\nMany of the initiates carry books of his writings.\n\nI need you to read these works and report back to me. If we can understand the Sargerei's motivations, perhaps we can undermine them.\n\nI last saw these books near the lake, on a table near the fountain, and in the house near the gardens.", completion = "I see... Socrethar is purely mad, but his reasoning is logical. No wonder so many draenei are turning to his cause.", objectives = "Read \"The Eredar Destiny,\" \"The Purpose of Unity,\" and \"The Promise of Eternity.\"", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35190] = { id = 35190, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Ancient Threat", description = "To the northwest, an Ancient has settled into a forest glade.\n\nI need someone to take care of this nuisance.\n\nThis should be a simple matter, even for an initiate like you.", completion = "Not bad.", objectives = "Kill Eldermoss.\n\nIf you lose your disguise, kill Sargerei enemies to collect a Sargerei Cowl, Sargerei Robe, and Sargerei Slippers to create a Sargerei Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35191] = { id = 35191, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shattering the Enemy", description = "While you carry out the pretense of obeying Zamaya's orders, we're going to sabotage the Sargerei under their very noses.\n\nAll around this village, you can find Felstorm Crystals. The enemy uses these objects to magnify their power.\n\nDestroy these crystals, and we'll slow their operations.", completion = "Very good. Our mission continues, undetected.", objectives = "Destroy 6 Felstorm Crystals.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35192] = { id = 35192, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See Reinforcements Teleport" }
quests[35193] = { id = 35193, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weapons Of Our Enemies", description = "We are doing well, initiate. We are close to gaining access to the council's chambers.\n\nMeanwhile, our subterfuge will continue. Atop the hill to the northeast, you will find the Sargerei training grounds.\n\nFor months they have been hammering, forging, and crafting the finest weapons to equip into battle.\n\nWe can undo their work in only moments, {name}.\n\nSteal their weapons. Let us see if they can still strike, then.", objectives = "Collect 4 Sargerei Weapons.\n\nIf you lose your disguise, kill Sargerei enemies to collect a Sargerei Cowl, Sargerei Robe, and Sargerei Slippers to create a Sargerei Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35194] = { id = 35194, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Facing Demons", description = "Time is running out, {name}. The Sargerei have opened a summoning portal on the hill to the west.\n\nI believe they are going to use this portal to bring an army of demons here, to Shadowmoon Valley.\n\nWe must stop them before this happens, no matter what the cost. Use this arcane bomb to destroy the portal.\n\nWe may blow our cover, but stopping the portal is more important right now.", completion = "<Mysteriously, Anchorite Laanda is gone. Did something happen here?>", objectives = "Defeat Invokaz, and destroy the demon gate.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35195] = { id = 35195, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Socrethar's Fury", description = "<Upon opening the scroll, you find a message from Anchorite Laanda.>\n\nI write this message hastily. I've been discovered. I'm being taken in front of Socrethar.\n\nYou must carry on our mission. I've learned that Soulbinder Zamaya holds a detailed plan of Socrethar's next attack.\n\nShe still trusts you, so you should be able to enter the main building. Please, find those plans, {name}!", progress = "Don't worry about me.", completion = "<Anchorite Laanda looks pale. He is not going to make it.>\n\n{name}... thank you for all that you have done.", objectives = "Confront Socrethar, then collect the Sargerei Battle Plans from Soulbinder Zamaya.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35196] = { id = 35196, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging Ahead", description = "<Anchorite Laanda's voice is barely a whisper.>\n\nYou must report back... to Khadgar.\n\nSocrethar means to take Shattrath. He will... continue to recruit followers... to his side...\n\nThank you for... helping me... in my final hour...\n\nLeave me... I would like to rest...", completion = "I see... Socrethar's ambitions begin with Shattrath and Auchindoun, but they do not end there.\n\nThank you for bringing this information to me, {name}.\n\nI will relay it to Archmage Khadgar immediately.", objectives = "Return to Khadgar's Servant at your garrison.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35197] = { id = 35197, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Forging Ahead", description = "<Anchorite Laanda's voice is barely a whisper.>\n\nYou must report back... to Khadgar.\n\nSocrethar means to take Shattrath. He will... continue to recruit followers... to his side...\n\nThank you for... helping me... in my final hour...\n\nLeave me... I would like to rest...", completion = "I see... Socrethar's ambitions begin with Shattrath and Auchindoun, but they do not end there.\n\nThank you for bringing this information to me, {name}.\n\nI will relay it to Archmage Khadgar immediately.", objectives = "Return to Khadgar's Servant at your garrison in Frostfire Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35201] = { id = 35201, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krixel" }
quests[35202] = { id = 35202, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shells for Xuk", description = "The magics Xuk is weaving will let you perform great acts, but preparations must be made before the spirits will bless us with their power.\n\nXuk needs many shells from the pesky goren. To gather them, Xuk will share a secret.\n\nApproach their tunnel craters and the goren will pour out. This way, you kill many at once.", progress = "Xuk Xuk.", completion = "Ahh, yes. Xuk is one step closer to performing a miracle.", objectives = "Collect 9 Goren Shells from Boneyard Gorgers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35203] = { id = 35203, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "More Materials", description = "Building a garrison is no simple task, and it does not happen without the proper resources.\n\nWe need a lot more materials.\n\nIf you find anything in the field let me know. We need all the help we can get.", objectives = "Collect 50 Garrison Resources.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35204] = { id = 35204, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen Power", description = "The botani use monstrous insect-like creatures to pollinate their bloom.\n\nThe pollen they carry has a number of powerful properties that would be of use to your garrison forces.\n\nIf you bring me a reserve of this pollen I should be able to convert it to something of value.", progress = "Do you have the pollen?", completion = "Keep this up and we'll make a survivalist out of you yet.", objectives = "Collect 20 Potent Pollen.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35205] = { id = 35205, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Burn the Bodies", description = "You don't understand. Anythin' these plant people don't infest they fatten up and then turn inta mulch.\n\nI say we take out their food source.\n\nThese botani got a few corpses lying around that I saw. Might be a good idea to burn those bodies.\n\nLet's find out if they can infest ash.", progress = "If I survive this, I'm gonna get even by becomin' a vegetarian.", completion = "Normally I'm not a violent dwarf, but I ain't about to sit by and get turned into a bush. And I ain't about to let others do the same.", objectives = "Burn 6 Mulching Bodies.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35206] = { id = 35206, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bushwhacker", description = "We are continuing the search for Thaelin's people, but these botani, they are a larger threat than we ever realized.\n\nTo infest their victims... monstrous.\n\nPlease, commander, if you find yourself in Evermorn Springs to our west, slay as many of those creatures as you can.\n\nStop them from committing such acts of horror. Bring them to justice.", completion = "Well done, commander. At every turn you seem to demonstrate an efficiency with war that even our most seasoned exarchs might fight to be challenging.", objectives = "Slay 7 Bloom Weavers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35207] = { id = 35207, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Coalpart's Revenge", description = "I'm so full I can't swing an axe even if I had one.\n\nTell ya what, we got a mutual interest here. I need yer help to get a little vengeance on the big botani at the back of this bloom. In return, I'll point ya in the right direction fer gettin' a secret weapon the botani keep.", progress = "Me mother always said: \"Burrian! Eat yer veggies!\"\n\nGoing to make her proud today.", completion = "Me mother always told me to eat me vegetables. I dunna think this is what she had in mind.", objectives = "Slay 3 Dew Masters.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35208] = { id = 35208, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Iron Down", description = "While you were away our rangari here found more clues leadin' to some of me other friends.\n\nBurrian Coalpart and Scorchbrow.\n\nProblem is, their trail heads right for Evermorn Springs to the west.\n\nPlease Commander, will ya get in there and save them from mulching?", completion = "Ah! It was terrible! They made me eat an' eat an' eat.\n\nDon' get me wrong, I enjoy a good meal but these plant people had me eatin' nuthin' but fruit.\n\nI canno' take it anymore.", objectives = "Find Burrian Coalpart in Evermorn Springs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35209] = { id = 35209, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Life Spring", description = "So we came here cause we needed a weapon we saw the botani using.\n\nHansel grabbed the artifact an' Scorchbrow an' I were supposed to grab the special water the thing runs on.\n\nWe didn't know that water so full of life forms an elemental.\n\nIf ya mosey up to the cauldron at the base of that fancy lookin' ancient artifact in Evermorn Springs, you'll be findin' this beast. If ya can kill it and get its water, we can use it when we get the rest of the artifact.", progress = "Now I see why some become Rangari. This is exciting.", completion = "You are carrying something of great power on you. I could feel it as you approached.", objectives = "Collect Waters of Utrophis.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35210] = { id = 35210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Great Escape", description = "A goren tunnel!\n\nOnce the cap is cleared, it's certain to lead outside of this Light-forsaken pit.", completion = "Those goren tunnels have proven useful.", objectives = "Clear the goren tunnel and use it to meet with Rexxar outside the Fissure of Fury.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35211] = { id = 35211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Preventing the Worst", description = "Have you seen all the fungus on the buildings in Pinchwhistle Point? It's only a matter of time 'til it releases enough spores to infest the whole coastline!\n\nThe remaining infected that are in Pinchwhistle Point will be too far gone for us to save later on, so let's do the right thing and put them out of their misery and prevent an even worse outbreak.\n\nI made some firebombs that will burn the fungus down, but I'll need you to place them while I set up the detonator.\n\nAre you up for it?", progress = "I'm almost done here. Have you placed all those firebombs yet?", completion = "Good work!\n\nOk I need to just finish setting up the ignition mechanism and we'll be all set.", objectives = "Place 5 Firebombs within Pinchwhistle Point.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35212] = { id = 35212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Deeproot", description = "Since yer all set up to take on trees and bushes now, I need ta ask for a favor.\n\nI came to Gorgrond in search of an expedition of me fellow Dark Irons that were headed this way. Sadly I lost 'em.\n\nI am goin' south to look for them. Thing is, south is nothing but botani, podlings, giant trees, and other mean, angry plants.\n\nYer lumber camp resources would be mighty appreciated. If ya help me look for me friends I swear we'll help ya in any way we can.", completion = "Ah good! Ya made it.\n\nThe lasses here insisted on comin' with, though they don't seem to like each other much.", objectives = "Meet Thaelin Darkanvil at Deeproot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35213] = { id = 35213, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Razorbloom", description = "Kaalya thinks she picked up a trail. Seems a bunch of dwarves went north to Razorbloom by the signs.\n\nProblem is that place is filled with plant people. I ain't much use against plant people.\n\nAre you willing to investigate?", completion = "The plant people fattened up my friends with fruit an' honey an' mead. Seems they were fattenin' them up for sure.", objectives = "Find clues to the whereabouts of Lera Ashtoes, Nori Sootstache, and Razzlebeard.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35214] = { id = 35214, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Infested", description = "D'kaan did not say it, but there were more rangari taken by the botani than the ones you found.\n\nHe believes they were slain. I fear worse.\n\nYou might dare to venture into the Razorbloom. If you do, you may discover what the botani do to their... \"prisoners.\"\n\nGive these poor souls a proper release.", progress = "One truth of Gorgrond: death is not the worst thing that can happen to you.", completion = "I thank you for doing what I could not.\n\nWhile it is the right thing to do, it is hard to loose the arrow when your target was once a friend.", objectives = "Slay 6 Infested.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35215] = { id = 35215, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Voice of Iyu", description = "Journal Entry 25 -\n\nThe botani got themselves a leader who calls himself... er... herself... er... itself the Voice of Iyu.\n\nSeems the botani see the genesaur as gods and only the most bossy of the botani get to speak on behalf of the genesaur.\n\nWhen we tried askin' it about the artifact we found back at the base it got all angry and sent off Lera and Nori and I ain't seen either of them since.\n\nI got a bad feelin' about this thing.", completion = "They mulched my friends? Those pointy branch wavers with their wee beady eyes! Thank ya for avenging ma friends.\n\nWe best be findin' the others before they get turned into plant food.", objectives = "Slay the Voice of Iyu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35216] = { id = 35216, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Super Seeds", description = "These seeds have been shielded with care by the botani.\n\nGreat power can be felt surging out of these tiny vessels of life.\n\nThese may prove useful.", progress = "What have ya found?", completion = "I may not know much about farmin' but I do know a power source when I see it. These seeds are packin' quite a punch.\n\nWay to think on yer feet and grab 'em, Commander.", objectives = "Collect Enriched Seeds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35217] = { id = 35217, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pearing It Up", description = "While you do Zamaya's work to earn her favor, we will secretly be sabotaging the Sargerei operation.\n\nIn the forests to the northwest, the podlings have gathered stolen pears from the farms. The little pests go crazy for the stuff.\n\nThe pears also happen to be a main food source for the Sargerei, so naturally, we're going to destroy the harvest.\n\nThat should take care of the podlings AND the draenei at the same time.", completion = "Excellent! I admit I love the taste of those pears as well, but it is a small price to pay to destroy our enemy.", objectives = "Destroy 10 Sugar Pears.\n\nIf you lose your disguise, kill Sargerei enemies to collect a Sargerei Cowl, Sargerei Robe, and Sargerei Slippers to create a Sargerei Disguise.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35218] = { id = 35218, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iron Horde Orders", description = "Spirit spotted some orders at the Iron Horde camp on the nearby bluff. You must have missed them when you were there. Could you look into it?", completion = "These orders are written with terrible handwriting.", objectives = "Look for weaponization orders at the Iron Horde camp in Crushfang's End.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35219] = { id = 35219, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Burning Front" }
quests[35220] = { id = 35220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Kharazos the Triumphant" }
quests[35221] = { id = 35221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Keeper" }
quests[35222] = { id = 35222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firing the Mayor", description = "The bottle has a large stopper in it with the label \"Property of Mayor Nurg Boltsnap.\"\n\nAs you gaze at the bottle you hear the sound of heavy machinery coming from the nearby marshland. \n\nAn investigation would be prudent. If the mayor has turned he will also need to be put down.", objectives = "Kill Mayor Nurg Boltsnap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35225] = { id = 35225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heavy Helping Hand", description = "Burrian gave us the coordinates of the Dark Iron base. They named it Moira's Reach.\n\nBut half way through buildin' it the base got infested with goren.\n\nIf you head south you should come to the structure. Just look for a big ol' cannon.\n\nWe will follow as soon as we get this bloody tank untangled.", completion = "Co... Commander? Well ain't you a sight for sore eyes?\n\nI didn't think anyone friendly was comin' for me.\n\nWe found an artifact that seemed pretty handy against the locals in the area but then those acid-mouthed roly polies showed up and started eatin' everything.\n\nHelp me up an' we can git to it.", objectives = "Find Dark Iron Dwarf survivors.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35227] = { id = 35227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ogre Diplomacy", description = "Ogres are ogres. Spirits or not, the Ango'rosh are not different.\n\nEven with their ritual books, they won't relinquish their power to you until you prove yourself.\n\nI've fought ogres my entire life, and there's only one way to earn that.\n\nKilling them outright.\n\nThe more Ango'rosh spirits and their pets as you take out while you're there, the more respect you'll command among them.", progress = "I hope you've extended our diplomatic hand to our ogre friends.", completion = "Another successful negotiation.", objectives = "Kill 10 Ango'rosh in the Ango'rosh Ruins.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35228] = { id = 35228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Firing the Mayor", description = "Ever since this zombie outbreak began I haven't seen the mayor at all. If he is infected then we could be in for a huge problem if he can escape out of town. Damn, we could be in for another zombie outbreak even!\n\nWe got to find him and make sure he doesn't escape! He used to ride in his custom shredder down on the shore line before the fungus started covering up everything. You might find him down there.", objectives = "Kill Mayor Nurg Boltsnap.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35229] = { id = 35229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Down the Goren Hole", description = "These beasts came at us so fast we didn't have time to mount a proper defense. They went right for the metal and chewed through any wall we had.\n\nIf we don't kill some of them soon they'll bring the whole fortress down on us.", progress = "All in a day's work, eh Commander?", completion = "You give me blackrock orcs, troggs, er evil leper gnomes an' we'd be fine. But these acid munchin' beasts are the end of us.", objectives = "Slay 5 goren in Moira's Reach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35231] = { id = 35231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spiritual Matters", description = "The spirits of the dead have long been drawn to Oshu'gun.\n\nAs long as I can remember, the woods have been filled with ancestral spirits making a ghostly pilgrimage to the heart of the mountain.\n\nHowever, I fear that what is transpiring here is not the normal spirit walk I have seen before.\n\nMake your way to the Ancestral Grounds and commune with the spirits there for guidance on this matter.", completion = "The situation here is dire, {name}, but I sensed that we would meet again.\n\nI do not hear the call of the void as loudly as the others, for I am not long dead and my body rests far from this place.\n\nWith time though, that will change.\n\nIf you are here to help, listen closely for time is short.", objectives = "Speak with the spirits at the Ancestral Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35232] = { id = 35232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Call of Oshu'gun", description = "The elements have spoken and a vision has been revealed, {name}.\n\nTogether we shall travel to the great mountain Oshu'gun and put an end to the dark disturbance there.\n\nIf what you saw in the vision is to be believed, then great danger awaits us.\n\nI will meet you in the Spirit Woods at the foot of Oshu'gun. When you are ready to depart, speak with Gixmo Moneycash and he will fly you there.", completion = "It has been many years since I have set foot within these woods.\n\nI was last here for the Kosh'harg many years ago when this place was shared amongst all clans. Those days have past and now only the Warsong banner flies here.", objectives = "Fly to the Spirit Woods.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35233] = { id = 35233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Just In Case", description = "When we set up shop the first thing we built was the cannon. Seemed like a good place fer it.\n\nWe started buildin' the base up around it when them chompin' acid spittin' varmints came crawlin' out of the ground.\n\nThe upside though is the cannon is built, just not loaded.\n\nWe have to go down to the bottom floor of this thing anyway so may as well grab some Doomshot if you see any on your way down.\n\nBetter to load the cannon and not need it than to need it and not have it loaded.", progress = "Ya got that ammo?", completion = "While I hope we don' need to fire the big gun, I kinda hope we can fire the big gun.", objectives = "Collect Doomshot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35234] = { id = 35234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Will of the Genesaur", description = "When the goren attacked we threw everything we had at them but they just kept comin'.\n\nSo some of the lads went and stole a fancy artifact from the botani.\n\nProblem was we couldn't get it to work. Now the artifact is sitting at the bottom of the bastion. To get to it you got to go all the way to the back of the tunnels past all them goren and find the wee tunnel that takes you farther underground.\n\nIf you retrieve it, it is yours.", progress = "Not fond of this place. If the plants ain't tryin' to kill you then the ground is tryin' to swallow ya up.", completion = "That artifact was useful until it ran out of juice. Hopefully you got some seeds and water for it.", objectives = "Recover the Will of the Genesaur.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35235] = { id = 35235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Iyu", description = "Did ya hear that?\n\nSounds like that genesaur wants its 'will' back. I told ya this place is nuthin' but bad luck.\n\nI'll git that shot ya gave me loaded properly and see if I can't weaken that thing up. You better get up there and deal with it though...", progress = "How goes your search?", completion = "That was a challenge.", objectives = "Defeat Iyu.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35236] = { id = 35236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orunai Coast" }
quests[35237] = { id = 35237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mor'gran Logworks" }
quests[35238] = { id = 35238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Owner", objectives = "Battle-Bot 8000 owner acquired: {name}.\n\nCurrent desire: Massage {name}'s enemies... to death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35239] = { id = 35239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "New Owner", objectives = "Battle-Bot 8000 owner acquired: {name}.\n\nCurrent directive: Massage {name}'s enemies... to death.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35240] = { id = 35240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bled Dry", description = "<The draenei spits out his last words.>\n\nThey kept us in cages. They... drain our blood, for... rituals...\n\n<He coughs violently.>\n\n...many left --\n\n    -- my... people...\n\n<The draenei dies.>", progress = "You should save those draenei, {name}. It is the right thing to do.", completion = "Well done, {name}.\n\nGiven, they are injured, half-starved, and poorly-equipped... but there is no blade so sharp as a vengeful spirit, no armor so thick as a righteous cause.", objectives = "Free the slaves from the 2 Bleeding Hollow Cages in Heartblood.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35241] = { id = 35241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for the Fallen", description = "Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven.\n\n<The grieving orc looks up at you.>\n\nMake them pay.", completion = "I admire your sense of duty, {name}. Even when your own survival hangs in the balance, you still find time to bring closure to a grieving widow. Well done.", objectives = "Slay 6 Bleeding Hollow orcs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35242] = { id = 35242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vengeance for the Fallen", description = "Too many of my people have fallen at the hands of the Bleeding Hollow. Their cruelty cannot be forgiven.\n\n<The grieving draenei looks up at you.>\n\nMake them pay.", completion = "I admire your sense of righteousness, {name}. Even when your own survival hangs in the balance, you still find time to avenge a grieving widow. Well done.", objectives = "Slay 6 Bleeding Hollow orcs.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35243] = { id = 35243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Lady's Gift", objectives = "I was bidden to find my way to you, and to swear my service. Whatever you need of me, I will offer. I take a particular pleasure in turning things to ashes.\n\nThe dark lady sends her regards.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35244] = { id = 35244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vignette: Skagg" }
quests[35245] = { id = 35245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Sentimental Relic", description = "My father's bangle sat here for ages before that imposter Ikiss stole it away.\n\nI thank you for returning it, but I have no need for keepsakes. Take it, with my blessing.\n\nIf there are still Talonpriests loyal to the true Talon King, please bring it to them.", progress = "Hm? What's that you have there?", completion = "Lithic actually spoke to you? Or, some shade of her at least... \n\nFascinating!", objectives = "Bring Lithic's Gift to Reshad in Veil Terokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35247] = { id = 35247, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zero Xuks Given", description = "The spirits have spoken to me. They believe the magnaron, Gro the Uncreator, will join our fight and lead his underlings against the Iron Horde.\n\nThis is an honor beyond any bestowed upon a Laughing Skull, at least in my time.\n\nI will commune with the magnaron, and together we shall destroy the Iron Horde.", completion = "The spirits of my ancestors have betrayed me! Their skulls are surely laughing.", objectives = "Speak with Bony Xuk to observe him communing with Gro the Uncreator.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35248] = { id = 35248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Harsh Reminder", description = "Welcome to the front lines, outsider, where the wastelands and the jungle collide.\n\nWhen their forces forget about the ferocity of the Laughing Skull, this is where we come to make them remember.\n\nBy fierce and merciless destruction we survive. This is the way of Gorgrond.\n\nJoin in! Let us see if you can withstand the brutality of our land.", completion = "I like killing things. And bones.", objectives = "Kill 8 denizens of the wasteland in Affliction Ridge.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35249] = { id = 35249, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Powering the Defenses", description = "It's good to see a Horde champion joining the fight.\n\nAuchindoun's defenses are faltering quickly. The few Auchenai soulpriests not on the front are working fervently to maintain them.\n\nSoulbinder Tuulani went inside the nearby Tomb of Lights to retrieve a backup power pylon and hasn't returned. If you can find her and get her and the pylon back here safely it would help greatly.", completion = "You look like you can fight. We need to get out of here!", objectives = "Find Soulbinder Tuulani in the Tomb of Lights.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35251] = { id = 35251, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bounty of Bladespire", description = "The sacking of this fortress is as much your victory as ours. It is only fair you should share in the bounty.\n\nI had the men prepare a chest for you. Take what you will.", completion = "This camp of yours could be fruitful, but it rests upon the footstep of Grom'gar. The Thunderlords are not likely to be welcome neighbors.", objectives = "Take your share of the plunder from Durotan's chest.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35252] = { id = 35252, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chest Reward Tracking Quest" }
quests[35253] = { id = 35253, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG: Thaelin Event Complete" }
quests[35254] = { id = 35254, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Retribution for the Light", description = "There are agents of darkness everywhere, fighting tooth and nail to envelop the world. The Light relies on us to balance the scale.\n\nYou have the power needed to destroy Teron'gor's demonic minions once and for all. Send them to the Twisting Nether in pieces!", completion = "Already I can feel the Light triumphing over darkness. We've done it!", objectives = "Kill 15 demons in Gul'rok.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35255] = { id = 35255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power of the Genesaur", description = "Commander, you now have the Will of the Genesaur along with the genesis water and enough seeds to grow an army. Not to mention the lives of the dwarves you saved.\n\nI would call this mission a success.\n\nI can help the dwarves mop up their operation here and see what we can salvage. In the meantime, you may want to bring the artifact to Maraad back at the outpost.", completion = "Well done, Commander. Many of the orcs have tried to master the power of the genesaur but I have never heard of any of them reaching this level of success.\n\nThis should provide us a substantial advantage in the days ahead.", objectives = "Speak with Vindicator Maraad at Highpass in Gorgrond.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35256] = { id = 35256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Heart Unbroken", description = "Though Gordawg's body lays shattered and lifeless upon the ground, a crystal heart glows brightly. The large crystal appears to be fully intact and all that remains of the mighty earthen fury.\n\nPerhaps Kalandrios will know what to make of the crystal.", sourceObjective = "Deliver the Heart of the Fury to Kalandrios.", sourceObjectiveStatus = "unverified-source-field" }
quests[35257] = { id = 35257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Power Unearthed", description = "What power could reduce a village to ashes in the blink of an eye? The Adherents claim it is the will of Rukhmar.\n\nA lie, obviously.\n\nThey did nothing to earn such power - in truth, they stumbled upon it rather unwittingly, in a hole in the ground.\n\nCome and visit me near the excavation site just west of here. We must understand their technology if we are to defeat it.", completion = "Ah yes, you've arrived just in time.", objectives = "Speak with Darkscryer Raastok near the Apexis Excavation.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35258] = { id = 35258, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Legacy of the Apexis", description = "The Apexis are long gone, but their legacy lies preserved in ancient chambers beneath Arak.\n\nLegions of dormant constructs; crystals flush with solar energy; magical techniques lost to the ages - the Apexis left behind caches of immense power, which the Adherents of Rukhmar have begun to unearth.\n\nBring me the cores of the re-activated constructs patrolling the excavation site. Those crystals are the basis of Apexis technology, and the key to our enemy's devastating power.", progress = "The Apexis had every advantage, and yet they vanished. What could have happened?", completion = "Excellent. With these we can begin to understand.", objectives = "Gather 5 Solar Cores from Apexis Guardians.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35259] = { id = 35259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sol Sisters", description = "When I was still a guard in Skyreach, I was tasked with protecting the sisters Veoryx and Krashyx.\n\nThey were prodigies. At an age when most sun acolytes could barely read, the sisters conjured familiars of pure sunlight to illuminate their textbooks in the small hours.\n\nNow they unravel the secrets of Apexis technology, and their excavation has just breached two ancient chambers.\n\nEnter those chambers and cut down the sisters before they reap the terrible rewards of their discovery.", progress = "<The Sol-Shapers are using their power to awaken these ancient Apexis constructs.>", completion = "<The core of this slumbering construct begins to hum softly.>", objectives = "Slay Sol-Shaper Veoryx and Sol-Shaper Krashyx.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35260] = { id = 35260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hardly Working", description = "Those who were not incinerated at Veil Akraz are forced to help the Adherents excavate the very weapons aimed at their heads.\n\nAnyone trying to escape is vaporized by the overseer's Apexis turret.\n\nWith these effigies, they won't know anyone has left! Place one near an enslaved worker and observe as it creates a perfect copy. It even cloaks the subject in shadow, so they can slip away safely!", completion = "Deception is the ultimate power. Remember this, {name}.", objectives = "Use Illusion Effigies to create decoys for 10 Enslaved Outcasts.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[35261] = { id = 35261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shot-Caller", description = "<Solar energy courses through the slumbering constructs, their ancient servos whirring to life all around you. It is too late to shut them down now.\n\nOutside, an arakkoa overseer bellows commands, each answered by the buzz of an Apexis beam carving away at the mountain.\n\nThat turret would make short work of the constructs - if you can command it.>", progress = "<A comfortable-looking chair with a socket in the arm rest.>", completion = "<The Apexis interface slides into place with a satisfying click. Seems this is the seat for taking full command of the turret.\n\nRifling through the cushions, you find a few spare coins, which you pocket.>", objectives = "Retrieve the Apexis Interface from Overseer Akrath.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
